import type { BankQuestion } from "@/lib/bank";

/** Percentage (Quantitative Aptitude): 208 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-percentage-1","question":"A price rises by 20% and then falls by 20%. The net change is:","options":["No change","4% decrease","4% increase","2% decrease"],"answer":1,"explanation":"Successive changes +20% and −20% give 20 − 20 + (20 × −20)/100 = −4%, i.e. ×1.2 × 0.8 = 0.96. 'No change' assumes the two cancel, but the fall is taken on a larger base.","difficulty":"hard","questionHi":"किसी वस्तु का मूल्य 20% बढ़ता है और फिर 20% घट जाता है। कुल परिवर्तन है:","optionsHi":["कोई परिवर्तन नहीं","4% की कमी","4% की वृद्धि","2% की कमी"],"explanationHi":"क्रमिक परिवर्तन +20% और −20% से 20 − 20 + (20 × −20)/100 = −4%, अर्थात् ×1.2 × 0.8 = 0.96। 'कोई परिवर्तन नहीं' मानने में यह माना जाता है कि दोनों कट जाते हैं, जबकि कमी बड़े आधार पर ली जाती है।","subtopic":"successive-change"},
  {"id":"quant-percentage-2","question":"12.5% expressed as a fraction is:","options":["1/4","1/6","1/8","1/12"],"answer":2,"explanation":"12.5% = 12.5/100 = 125/1000 = 1/8. 1/4 is 25%, and 1/12 is 8.33%, both common slips when halving or misreading.","difficulty":"easy","questionHi":"12.5% को भिन्न के रूप में लिखने पर प्राप्त होता है:","optionsHi":["1/4","1/6","1/8","1/12"],"explanationHi":"12.5% = 12.5/100 = 125/1000 = 1/8। 1/4 का मान 25% है और 1/12 का मान 8.33% है; आधा करते समय या गलत पढ़ने पर ये दोनों भूलें आम हैं।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-3","question":"If 40% of a number is 80, the number is:","options":["120","160","200","320"],"answer":2,"explanation":"40% of N = 80, so N = 80 × 100/40 = 200. 120 adds 40 to 80, and 320 multiplies 80 by 4 instead of dividing by 0.4.","difficulty":"moderate","questionHi":"यदि किसी संख्या का 40% 80 है, तो संख्या है:","optionsHi":["120","160","200","320"],"explanationHi":"N का 40% = 80, अतः N = 80 × 100/40 = 200। 120 में 80 में 40 जोड़ दिया गया है, और 320 में 0.4 से भाग देने के बजाय 80 को 4 से गुणा कर दिया गया है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-4","question":"In an election between two candidates, the winner got 60% of the votes and won by 1,200 votes. The total number of votes was:","options":["3,000","4,800","6,000","7,200"],"answer":2,"explanation":"The margin is 60% − 40% = 20% of the votes, so 20% = 1,200 and total = 6,000.","difficulty":"very-hard","questionHi":"दो उम्मीदवारों के बीच एक चुनाव में विजेता को 60% मत मिले और वह 1,200 मतों से जीता। कुल मतों की संख्या थी:","optionsHi":["3,000","4,800","6,000","7,200"],"explanationHi":"जीत का अंतर 60% − 40% = 20% मत है, अतः 20% = 1,200 और कुल मत = 6,000।","subtopic":"election-votes"},
  {"id":"quant-percentage-5","question":"What is 35% of 240?","options":["72","84","96","156"],"answer":1,"explanation":"35% of 240 = 0.35 × 240 = 84 (10% is 24, so 30% is 72 and 5% is 12). 72 stops at 30%, 96 is 40%, and 156 is 65% of 240.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"240 का 35% कितना है?","optionsHi":["72","84","96","156"],"explanationHi":"240 का 35% = 0.35 × 240 = 84 (10% = 24, अतः 30% = 72 और 5% = 12)। 72 केवल 30% है, 96, 40% है, और 156, 240 का 65% है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-6","question":"A shop's rent rises by 10% in one year and by 20% in the next. What is the total percentage rise in the rent over the two years?","options":["30%","31%","32%","34%"],"answer":2,"explanation":"1.1 × 1.2 = 1.32, a 32% rise; equivalently 10 + 20 + (10 × 20)/100 = 32%. 30% simply adds the two rates and ignores the second rise being taken on the already raised rent.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk","questionHi":"किसी दुकान का किराया एक वर्ष में 10% और अगले वर्ष 20% बढ़ता है। दो वर्षों में किराए में कुल कितने प्रतिशत की वृद्धि हुई?","optionsHi":["30%","31%","32%","34%"],"explanationHi":"1.1 × 1.2 = 1.32, अर्थात् 32% वृद्धि; या 10 + 20 + (10 × 20)/100 = 32%। 30% में दोनों दरें सीधे जोड़ दी गई हैं और यह अनदेखा किया गया है कि दूसरी वृद्धि पहले से बढ़े हुए किराए पर होती है।","subtopic":"successive-change"},
  {"id":"quant-percentage-7","question":"In a two-candidate election, 20% of the voters on the list did not vote and all the votes cast were valid. The winner got 62% of the votes cast and won by 4,800 votes. How many voters were on the list?","options":["16,000","20,000","24,000","25,000"],"answer":3,"explanation":"The margin is 62% − 38% = 24% of the votes cast, so votes cast = 4,800 ÷ 0.24 = 20,000. These are 80% of the list, so the list has 20,000 ÷ 0.8 = 25,000 voters. 20,000 stops at the votes cast, while 24,000 and 16,000 add or take away 20% instead of dividing by 0.8.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"दो उम्मीदवारों के एक चुनाव में मतदाता सूची के 20% मतदाताओं ने मतदान नहीं किया और डाले गए सभी मत वैध थे। विजेता को डाले गए मतों का 62% मिला और वह 4,800 मतों से जीता। सूची में कितने मतदाता थे?","optionsHi":["16,000","20,000","24,000","25,000"],"explanationHi":"जीत का अंतर डाले गए मतों का 62% − 38% = 24% है, अतः डाले गए मत = 4,800 ÷ 0.24 = 20,000। ये सूची के 80% हैं, अतः सूची में 20,000 ÷ 0.8 = 25,000 मतदाता हैं। 20,000 डाले गए मतों पर ही रुक जाता है, जबकि 24,000 और 16,000 में 0.8 से भाग देने के बजाय 20% जोड़ा या घटाया गया है।","subtopic":"election-votes"},
  {"id":"quant-percentage-8","question":"The price of sugar rises by 25%. By what percent must a family cut consumption to keep spending unchanged?","options":["20%","25%","30%","33⅓%"],"answer":0,"explanation":"Cut = r/(100 + r) × 100 = 25/125 × 100 = 20%, because the new price is 5/4 of the old, so consumption must become 4/5. 25% is the classic trap of cutting by the same percent as the rise.","difficulty":"very-hard","source":"SSC CGL · SBI Clerk","questionHi":"चीनी के मूल्य में 25% की वृद्धि हो जाती है। एक परिवार को अपनी खपत कितने प्रतिशत कम करनी चाहिए ताकि व्यय अपरिवर्तित रहे?","optionsHi":["20%","25%","30%","33⅓%"],"explanationHi":"कमी = r/(100 + r) × 100 = 25/125 × 100 = 20%, क्योंकि नया मूल्य पुराने का 5/4 है, इसलिए खपत 4/5 हो जानी चाहिए। 25% वही प्रसिद्ध जाल है जिसमें वृद्धि के बराबर प्रतिशत की कटौती कर दी जाती है।","subtopic":"price-consumption"},
  {"id":"quant-percentage-9","question":"What percent of 2 kg is 250 g?","options":["12.5%","25%","8%","1.25%"],"answer":0,"explanation":"250 g ÷ 2,000 g = 1/8 = 12.5%. Both quantities must be in the same unit first; 25% is the slip of using 1 kg as the base.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"2 kg का कितने प्रतिशत 250 g है?","optionsHi":["12.5%","25%","8%","1.25%"],"explanationHi":"250 g ÷ 2,000 g = 1/8 = 12.5%। दोनों राशियों को पहले एक ही इकाई में बदलना आवश्यक है; 25% में 1 kg को आधार मान लेने की भूल है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-10","question":"If 35% of a number exceeds 25% of the same number by 14, the number is:","options":["140","100","280","56"],"answer":0,"explanation":"35% − 25% = 10% of the number = 14, so the number = 140. Check: 35% of 140 = 49 and 25% of 140 = 35, difference 14.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"यदि किसी संख्या का 35%, उसी संख्या के 25% से 14 अधिक है, तो संख्या है:","optionsHi":["140","100","280","56"],"explanationHi":"35% − 25% = संख्या का 10% = 14, अतः संख्या = 140। जाँच: 140 का 35% = 49 और 140 का 25% = 35, अंतर 14 है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-11","question":"A's salary is 25% more than B's. B's salary is less than A's by:","options":["33⅓%","20%","75%","25%"],"answer":1,"explanation":"Let B = 100, so A = 125. B is less than A by 25 on a base of 125 = 20%. The base changes from B to A, so the answer is not 25%.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"A का वेतन B के वेतन से 25% अधिक है। B का वेतन A के वेतन से कम है:","optionsHi":["33⅓%","20%","75%","25%"],"explanationHi":"माना B = 100, तो A = 125। B, A से 25 कम है और आधार 125 है, अतः कमी = 20%। आधार B से बदलकर A हो जाता है, इसलिए उत्तर 25% नहीं है।","subtopic":"successive-change"},
  {"id":"quant-percentage-12","question":"The population of a town grows 10% every year. If the present population is 12,100, what was it two years ago?","options":["10,890","9,900","9,680","10,000"],"answer":3,"explanation":"P × 1.1 × 1.1 = 12,100, so P = 12,100/1.21 = 10,000. Subtracting 10% twice (12,100 → 10,890 → 9,801) is the wrong-base slip.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"एक कस्बे की जनसंख्या हर वर्ष 10% बढ़ती है। यदि वर्तमान जनसंख्या 12,100 है, तो दो वर्ष पहले यह कितनी थी?","optionsHi":["10,890","9,900","9,680","10,000"],"explanationHi":"P × 1.1 × 1.1 = 12,100, अतः P = 12,100/1.21 = 10,000। 10% को दो बार घटाना (12,100 → 10,890 → 9,801) गलत आधार लेने की भूल है।","subtopic":"population-depreciation"},
  {"id":"quant-percentage-13","question":"A student scoring 30% fails by 20 marks, while a student scoring 50% gets 30 marks more than the pass mark. The pass mark is:","options":["95","250","75","125"],"answer":0,"explanation":"The gap between 30% and 50% is 20 + 30 = 50 marks, so 20% = 50 and maximum marks = 250. Pass mark = 30% of 250 + 20 = 75 + 20 = 95.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"30% अंक पाने वाला एक छात्र 20 अंकों से अनुत्तीर्ण हो जाता है, जबकि 50% अंक पाने वाला छात्र उत्तीर्ण अंक से 30 अंक अधिक पाता है। उत्तीर्ण अंक है:","optionsHi":["95","250","75","125"],"explanationHi":"30% और 50% के बीच का अंतर 20 + 30 = 50 अंक है, अतः 20% = 50 और पूर्णांक = 250। उत्तीर्ण अंक = 250 के 30% + 20 = 75 + 20 = 95।","subtopic":"marks-exams"},
  {"id":"quant-percentage-14","question":"Rohit spends 40% of his income on rent and 30% of the remainder on food. If he saves ₹8,400, his income is:","options":["₹12,000","₹20,000","₹28,000","₹14,000"],"answer":1,"explanation":"After rent 60% remains; after food 70% of that remains, i.e. 0.6 × 0.7 = 42% of income = ₹8,400. Income = 8,400/0.42 = ₹20,000. Treating food as 30% of the whole income (saving 30%) gives the wrong ₹28,000.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"रोहित अपनी आय का 40% किराये पर और शेष का 30% भोजन पर खर्च करता है। यदि वह ₹8,400 बचाता है, तो उसकी आय है:","optionsHi":["₹12,000","₹20,000","₹28,000","₹14,000"],"explanationHi":"किराये के बाद 60% बचता है; भोजन के बाद उसका 70% बचता है, अर्थात् 0.6 × 0.7 = आय का 42% = ₹8,400। आय = 8,400/0.42 = ₹20,000। भोजन को पूरी आय का 30% मानने (यानी बचत 30% मानने) पर गलत उत्तर ₹28,000 आता है।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-15","question":"The price of petrol was raised by 20% and later by another 25%. By what percent must a motorist cut consumption so that his expenditure stays the same?","options":["40%","45%","50%","33⅓%"],"answer":3,"explanation":"Net price factor = 1.2 × 1.25 = 1.5. Consumption must become 1/1.5 = 2/3 of the original, a cut of 1/3 = 33⅓%. Adding the rises to 45% and cutting 45% are both wrong.","difficulty":"hard","source":"SSC CGL · CDS","questionHi":"पेट्रोल का मूल्य 20% बढ़ाया गया और बाद में 25% और बढ़ाया गया। एक वाहन चालक को अपनी खपत कितने प्रतिशत घटानी चाहिए ताकि उसका व्यय समान रहे?","optionsHi":["40%","45%","50%","33⅓%"],"explanationHi":"मूल्य का कुल गुणक = 1.2 × 1.25 = 1.5। खपत मूल की 1/1.5 = 2/3 हो जानी चाहिए, यानी 1/3 = 33⅓% की कमी। वृद्धियों को जोड़कर 45% लेना और 45% घटाना, दोनों गलत हैं।","subtopic":"price-consumption"},
  {"id":"quant-percentage-16","question":"In an examination 65% of candidates passed in English, 55% passed in Mathematics and 30% failed in both. If 150 candidates passed in both subjects, the total number of candidates is:","options":["350","300","250","400"],"answer":1,"explanation":"Passed in at least one = 100 − 30 = 70%. Passed in both = 65 + 55 − 70 = 50% = 150, so total = 300.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक परीक्षा में 65% परीक्षार्थी अंग्रेज़ी में, 55% गणित में उत्तीर्ण हुए और 30% दोनों में अनुत्तीर्ण रहे। यदि 150 परीक्षार्थी दोनों विषयों में उत्तीर्ण हुए, तो कुल परीक्षार्थियों की संख्या है:","optionsHi":["350","300","250","400"],"explanationHi":"कम से कम एक में उत्तीर्ण = 100 − 30 = 70%। दोनों में उत्तीर्ण = 65 + 55 − 70 = 50% = 150, अतः कुल = 300।","subtopic":"marks-exams"},
  {"id":"quant-percentage-17","question":"In an election between two candidates, 15% of the listed voters did not vote and 350 votes were declared invalid. The winner got 60% of the valid votes and won by 1,800 votes. The number of voters on the list was:","options":["11,000","9,000","9,350","10,500"],"answer":0,"explanation":"The margin is 60% − 40% = 20% of valid votes = 1,800, so valid votes = 9,000 and votes cast = 9,000 + 350 = 9,350. That is 85% of the list, so the list has 9,350/0.85 = 11,000 voters.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"दो उम्मीदवारों के बीच एक चुनाव में सूचीबद्ध मतदाताओं में से 15% ने मतदान नहीं किया और 350 मत अवैध घोषित हुए। विजेता को वैध मतों का 60% मिला और वह 1,800 मतों से जीता। सूची में मतदाताओं की संख्या थी:","optionsHi":["11,000","9,000","9,350","10,500"],"explanationHi":"जीत का अंतर 60% − 40% = वैध मतों का 20% = 1,800, अतः वैध मत = 9,000 और डाले गए मत = 9,000 + 350 = 9,350। यह सूची का 85% है, अतः सूची में 9,350/0.85 = 11,000 मतदाता हैं।","subtopic":"election-votes"},
  {"id":"quant-percentage-18","question":"A number is increased by x% and the result is then decreased by x%. If the final number is 4% less than the original, x is:","options":["4","40","20","2"],"answer":2,"explanation":"A rise and fall of x% each gives a net change of −x²/100 %. So x²/100 = 4, x² = 400, x = 20. Check: 100 → 120 → 96.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"किसी संख्या में x% की वृद्धि की जाती है और फिर परिणाम में x% की कमी की जाती है। यदि अंतिम संख्या मूल संख्या से 4% कम है, तो x है:","optionsHi":["4","40","20","2"],"explanationHi":"x% की वृद्धि और फिर x% की कमी से कुल परिवर्तन −x²/100 % होता है। अतः x²/100 = 4, x² = 400, x = 20। जाँच: 100 → 120 → 96।","subtopic":"successive-change"},
  {"id":"quant-percentage-19","question":"The price of rice rose by 20%, but a family cut its consumption so that its expenditure rose by only 8%. The consumption fell by:","options":["20%","12%","10%","8%"],"answer":2,"explanation":"Expenditure = price × quantity, so 1.2 × q = 1.08 gives q = 0.9, a fall of 10%. The slip 20% − 8% = 12% ignores that the percentages act on different bases.","difficulty":"hard","source":"SSC CGL · SBI PO","questionHi":"चावल का मूल्य 20% बढ़ गया, लेकिन एक परिवार ने अपनी खपत इस प्रकार घटाई कि उसका व्यय केवल 8% बढ़ा। खपत में कमी हुई:","optionsHi":["20%","12%","10%","8%"],"explanationHi":"व्यय = मूल्य × मात्रा, अतः 1.2 × q = 1.08 से q = 0.9, यानी 10% की कमी। 20% − 8% = 12% वाली भूल इस बात को अनदेखा करती है कि प्रतिशत अलग-अलग आधारों पर लगते हैं।","subtopic":"price-consumption"},
  {"id":"quant-percentage-20","question":"A's income is 20% more than B's and B's income is 25% less than C's. A's income as a percentage of C's is:","options":["85%","95%","105%","90%"],"answer":3,"explanation":"Let C = 100; B = 75; A = 1.2 × 75 = 90. So A is 90% of C. Simply adding +20% and −25% to get 95% is the wrong-base error.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"A की आय B की आय से 20% अधिक है और B की आय C की आय से 25% कम है। A की आय, C की आय का कितना प्रतिशत है?","optionsHi":["85%","95%","105%","90%"],"explanationHi":"माना C = 100; B = 75; A = 1.2 × 75 = 90। अतः A, C का 90% है। +20% और −25% को सीधे जोड़कर 95% निकालना गलत आधार लेने की भूल है।","subtopic":"successive-change"},
  {"id":"quant-percentage-21","question":"In a college 60% of the students are boys. 20% of the boys and 30% of the girls come from outside the state. If 480 students come from outside the state, the total strength of the college is:","options":["1,600","2,000","1,920","2,400"],"answer":1,"explanation":"Outside-state fraction = 0.6 × 0.2 + 0.4 × 0.3 = 0.12 + 0.12 = 0.24 of the total. Total = 480/0.24 = 2,000. Using the average 25% of the two rates gives the wrong 1,920.","difficulty":"very-hard","source":"SSC CGL · SBI PO","questionHi":"एक कॉलेज में 60% विद्यार्थी लड़के हैं। 20% लड़के और 30% लड़कियाँ राज्य के बाहर से आते हैं। यदि राज्य के बाहर से 480 विद्यार्थी आते हैं, तो कॉलेज की कुल संख्या है:","optionsHi":["1,600","2,000","1,920","2,400"],"explanationHi":"राज्य के बाहर का अंश = 0.6 × 0.2 + 0.4 × 0.3 = 0.12 + 0.12 = कुल का 0.24। कुल = 480/0.24 = 2,000। दोनों दरों का औसत 25% लेने पर गलत उत्तर 1,920 आता है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-22","question":"40 litres of a solution contains 15% alcohol. How much pure alcohol must be added so that the solution contains 32% alcohol?","options":["6.8 litres","8 litres","12 litres","10 litres"],"answer":3,"explanation":"Alcohol now = 6 L. Adding x L of pure alcohol: 6 + x = 0.32(40 + x), so 6 + x = 12.8 + 0.32x, 0.68x = 6.8, x = 10. Check: 16/50 = 32%. The slip 0.17 × 40 = 6.8 ignores that the total also rises.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"15% अल्कोहल वाले 40 लीटर घोल में कितना शुद्ध अल्कोहल मिलाया जाए कि घोल में 32% अल्कोहल हो जाए?","optionsHi":["6.8 लीटर","8 लीटर","12 लीटर","10 लीटर"],"explanationHi":"अभी अल्कोहल = 6 L। x L शुद्ध अल्कोहल मिलाने पर: 6 + x = 0.32(40 + x), अतः 6 + x = 12.8 + 0.32x, 0.68x = 6.8, x = 10। जाँच: 16/50 = 32%। 0.17 × 40 = 6.8 वाली भूल इस बात को अनदेखा करती है कि कुल मात्रा भी बढ़ जाती है।","subtopic":"mixtures-concentration"},
  {"id":"quant-percentage-23","question":"How many of the following statements are correct?\n1. A number increased by 10% and then decreased by 10% falls by 1% overall.\n2. If A is 50% more than B, then B is 50% less than A.\n3. 20% of 30% of a number equals 6% of that number.\n4. If a price rises by 25%, cutting consumption by 20% keeps the expenditure unchanged.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"1 is true (1.1 × 0.9 = 0.99). 2 is false: B is 50/150 = 33⅓% less than A. 3 is true (0.2 × 0.3 = 0.06). 4 is true (1.25 × 0.8 = 1). So three statements are correct.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"निम्नलिखित में से कितने कथन सही हैं?\n1. किसी संख्या में 10% वृद्धि और फिर 10% कमी करने पर कुल मिलाकर 1% की कमी होती है।\n2. यदि A, B से 50% अधिक है, तो B, A से 50% कम है।\n3. किसी संख्या के 30% का 20%, उस संख्या के 6% के बराबर होता है।\n4. यदि मूल्य में 25% की वृद्धि हो, तो खपत में 20% की कमी करने से व्यय अपरिवर्तित रहता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"1 सही है (1.1 × 0.9 = 0.99)। 2 गलत है: B, A से 50/150 = 33⅓% कम है। 3 सही है (0.2 × 0.3 = 0.06)। 4 सही है (1.25 × 0.8 = 1)। अतः तीन कथन सही हैं।","subtopic":"successive-change"},
  {"id":"quant-percentage-24","question":"A 20% fall in the price of wheat lets a housewife buy 5 kg more for ₹400. The reduced price per kg is:","options":["₹20","₹16","₹25","₹12"],"answer":1,"explanation":"With the new price being 80% of the old, ₹400 buys 5/4 of the old quantity, so the extra 1/4 = 5 kg and the old quantity was 20 kg at ₹20/kg. Reduced price = 0.8 × 20 = ₹16. ₹20 is the original price, not the reduced one.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"गेहूँ के मूल्य में 20% की गिरावट से एक गृहिणी ₹400 में 5 kg अधिक खरीद पाती है। घटा हुआ मूल्य प्रति kg है:","optionsHi":["₹20","₹16","₹25","₹12"],"explanationHi":"नया मूल्य पुराने का 80% होने से ₹400 में पुरानी मात्रा की 5/4 मात्रा आती है, अतः अतिरिक्त 1/4 = 5 kg और पुरानी मात्रा 20 kg थी, ₹20/kg की दर से। घटा हुआ मूल्य = 0.8 × 20 = ₹16। ₹20 मूल मूल्य है, घटा हुआ मूल्य नहीं।","subtopic":"price-consumption"},
  {"id":"quant-percentage-25","question":"A man's salary rose by 10% in 2023, by 20% in 2024 and was cut by 25% in 2025. Compared with his 2022 salary, his 2025 salary is:","options":["5% less","5% more","1% less","1% more"],"answer":2,"explanation":"Net factor = 1.1 × 1.2 × 0.75 = 0.99, so the salary is 1% less. Adding the percentages (10 + 20 − 25 = +5%) ignores compounding.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"एक व्यक्ति का वेतन 2023 में 10%, 2024 में 20% बढ़ा और 2025 में 25% घटा दिया गया। 2022 के वेतन की तुलना में उसका 2025 का वेतन है:","optionsHi":["5% कम","5% अधिक","1% कम","1% अधिक"],"explanationHi":"कुल गुणक = 1.1 × 1.2 × 0.75 = 0.99, अतः वेतन 1% कम है। प्रतिशतों को जोड़ना (10 + 20 − 25 = +5%) चक्रवृद्धि प्रभाव को अनदेखा करना है।","subtopic":"successive-change"},
  {"id":"quant-percentage-26","question":"In an election among three candidates A, B and C, A got 40% of the votes and B got 35%. If A defeated C by 4,500 votes, the number of votes B received was:","options":["7,500","9,000","10,500","12,000"],"answer":2,"explanation":"C got 100 − 40 − 35 = 25%. A − C = 15% of total = 4,500, so total = 30,000 and B = 35% of 30,000 = 10,500.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"तीन उम्मीदवारों A, B और C के बीच एक चुनाव में A को 40% मत और B को 35% मत मिले। यदि A, C से 4,500 मतों से जीता, तो B को मिले मतों की संख्या थी:","optionsHi":["7,500","9,000","10,500","12,000"],"explanationHi":"C को 100 − 40 − 35 = 25% मत मिले। A − C = कुल का 15% = 4,500, अतः कुल = 30,000 और B = 30,000 का 35% = 10,500।","subtopic":"election-votes"},
  {"id":"quant-percentage-27","question":"A firm has 1,000 employees of whom 60% are men. 50% of the men and 25% of the women are graduates. What percent of the non-graduate employees are women?","options":["50%","45%","60%","40%"],"answer":0,"explanation":"Men 600, women 400. Non-graduate men = 50% of 600 = 300; non-graduate women = 75% of 400 = 300. Women form 300/600 = 50% of non-graduates. Using 40% (women's share of all staff) is the wrong base.","difficulty":"very-hard","source":"SSC CGL · SBI PO","questionHi":"एक फर्म में 1,000 कर्मचारी हैं जिनमें 60% पुरुष हैं। 50% पुरुष और 25% महिलाएँ स्नातक हैं। गैर-स्नातक कर्मचारियों में कितने प्रतिशत महिलाएँ हैं?","optionsHi":["50%","45%","60%","40%"],"explanationHi":"पुरुष 600, महिलाएँ 400। गैर-स्नातक पुरुष = 600 का 50% = 300; गैर-स्नातक महिलाएँ = 400 का 75% = 300। गैर-स्नातकों में महिलाएँ 300/600 = 50% हैं। 40% लेना (समस्त स्टाफ में महिलाओं का अंश) गलत आधार है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-28","question":"In a test Riya scored 60% and Priya scored 75% of the maximum marks, and Priya's score exceeded Riya's by 45 marks. If the pass mark is 40%, by how many marks did Riya clear the pass mark?","options":["120","45","75","60"],"answer":3,"explanation":"15% of the maximum = 45, so maximum marks = 300. Riya scored 180, the pass mark is 120, so she cleared it by 60 marks.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक परीक्षा में रिया ने अधिकतम अंकों का 60% और प्रिया ने 75% अंक प्राप्त किए, और प्रिया के अंक रिया से 45 अधिक थे। यदि उत्तीर्ण अंक 40% हैं, तो रिया उत्तीर्ण अंक से कितने अंक अधिक पाकर उत्तीर्ण हुई?","optionsHi":["120","45","75","60"],"explanationHi":"अधिकतम अंकों का 15% = 45, अतः अधिकतम अंक = 300। रिया के अंक 180 हैं, उत्तीर्ण अंक 120 हैं, इसलिए वह 60 अंक अधिक पाकर उत्तीर्ण हुई।","subtopic":"marks-exams"},
  {"id":"quant-percentage-29","question":"What is 15% of 25% of 1,600?","options":["64","60","40","600"],"answer":1,"explanation":"25% of 1,600 = 400; 15% of 400 = 60. Equivalently 0.15 × 0.25 × 1,600 = 60.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"1,600 के 25% का 15% कितना होता है?","optionsHi":["64","60","40","600"],"explanationHi":"1,600 का 25% = 400; 400 का 15% = 60। इसी प्रकार 0.15 × 0.25 × 1,600 = 60।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-30","question":"A's income is 40% less than B's. By what percent is B's income more than A's?","options":["66⅔%","40%","60%","28⅓%"],"answer":0,"explanation":"Let B = 100, so A = 60. B exceeds A by 40, which is 40/60 × 100 = 66⅔% of A. 40% uses B as the base by mistake.","difficulty":"moderate","source":"SSC CGL","questionHi":"A की आय B की आय से 40% कम है। B की आय A की आय से कितने प्रतिशत अधिक है?","optionsHi":["66⅔%","40%","60%","28⅓%"],"explanationHi":"माना B = 100, तो A = 60। B, A से 40 अधिक है, जो A का 40/60 × 100 = 66⅔% है। 40% में भूल से B को आधार ले लिया गया है।","subtopic":"successive-change"},
  {"id":"quant-percentage-31","question":"The price of an item rises by 30% and a customer buys 10% less of it. By what percent does his expenditure change?","options":["20% increase","3% increase","13% increase","17% increase"],"answer":3,"explanation":"Expenditure = price × quantity = 1.30 × 0.90 = 1.17 of the original, a 17% increase. 20% wrongly subtracts 30 − 10 directly.","difficulty":"moderate","source":"SSC CGL","questionHi":"किसी वस्तु का मूल्य 30% बढ़ जाता है और एक ग्राहक उसे 10% कम खरीदता है। उसके व्यय में कितने प्रतिशत परिवर्तन होता है?","optionsHi":["20% की वृद्धि","3% की वृद्धि","13% की वृद्धि","17% की वृद्धि"],"explanationHi":"व्यय = मूल्य × मात्रा = 1.30 × 0.90 = मूल का 1.17, अर्थात् 17% की वृद्धि। 20% में 30 − 10 सीधे घटा दिया गया है, जो गलत है।","subtopic":"price-consumption"},
  {"id":"quant-percentage-32","question":"Ravi spends 75% of his income. His income rises by 20% and his expenditure by 10%. By what percent do his savings increase?","options":["30%","10%","50%","40%"],"answer":2,"explanation":"Income 100, spending 75, saving 25. New income 120, new spending 82.5, new saving 37.5. Increase = 12.5/25 = 50%.","difficulty":"hard","source":"SSC CGL Tier-2","questionHi":"रवि अपनी आय का 75% खर्च करता है। उसकी आय में 20% और व्यय में 10% की वृद्धि होती है। उसकी बचत कितने प्रतिशत बढ़ती है?","optionsHi":["30%","10%","50%","40%"],"explanationHi":"आय 100, व्यय 75, बचत 25। नई आय 120, नया व्यय 82.5, नई बचत 37.5। वृद्धि = 12.5/25 = 50%।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-33","question":"A town's population rose 20% in the first year, fell 10% in the second and rose 20% in the third, reaching 38,880. What was it at the start?","options":["32,400","30,000","27,000","31,104"],"answer":1,"explanation":"Overall factor = 1.2 × 0.9 × 1.2 = 1.296. Initial = 38,880 ÷ 1.296 = 30,000. 32,400 undoes only the last rise; 31,104 subtracts 20% of the final figure instead of dividing.","difficulty":"hard","source":"SSC CGL Tier-2","questionHi":"एक कस्बे की जनसंख्या पहले वर्ष में 20% बढ़ी, दूसरे वर्ष में 10% घटी और तीसरे वर्ष में 20% बढ़कर 38,880 हो गई। शुरू में यह कितनी थी?","optionsHi":["32,400","30,000","27,000","31,104"],"explanationHi":"कुल गुणक = 1.2 × 0.9 × 1.2 = 1.296। प्रारंभिक = 38,880 ÷ 1.296 = 30,000। 32,400 में केवल अंतिम वृद्धि को हटाया गया है; 31,104 में भाग देने के बजाय अंतिम संख्या का 20% घटा दिया गया है।","subtopic":"population-depreciation"},
  {"id":"quant-percentage-34","question":"A's salary is 25% more than B's, and B's salary is 20% more than C's. If A earns ₹4,500 more than C, what is C's salary?","options":["₹9,000","₹10,000","₹10,800","₹7,500"],"answer":0,"explanation":"A = 1.25 × 1.2 × C = 1.5C, so A − C = 0.5C = 4,500 and C = ₹9,000. Taking 25% + 20% = 45% gives the slip ₹10,000.","difficulty":"hard","source":"SSC CGL","questionHi":"A का वेतन B के वेतन से 25% अधिक है और B का वेतन C के वेतन से 20% अधिक है। यदि A, C से ₹4,500 अधिक कमाता है, तो C का वेतन कितना है?","optionsHi":["₹9,000","₹10,000","₹10,800","₹7,500"],"explanationHi":"A = 1.25 × 1.2 × C = 1.5C, अतः A − C = 0.5C = 4,500 और C = ₹9,000। 25% + 20% = 45% लेने पर गलत उत्तर ₹10,000 आता है।","subtopic":"successive-change"},
  {"id":"quant-percentage-35","question":"Ram spends 20% of his income on rent, 30% of the remainder on his children's education and 25% of what is then left on food. He is left with ₹12,600. What is his income?","options":["₹50,400","₹25,200","₹28,000","₹30,000"],"answer":3,"explanation":"Left = income × 0.80 × 0.70 × 0.75 = 0.42 × income. Income = 12,600 ÷ 0.42 = ₹30,000. Subtracting 20 + 30 + 25 = 75% of the whole gives ₹50,400, the common slip.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"राम अपनी आय का 20% किराये पर, शेष का 30% बच्चों की शिक्षा पर और उसके बाद बचे हुए का 25% भोजन पर खर्च करता है। उसके पास ₹12,600 बचते हैं। उसकी आय कितनी है?","optionsHi":["₹50,400","₹25,200","₹28,000","₹30,000"],"explanationHi":"बचा हुआ = आय × 0.80 × 0.70 × 0.75 = 0.42 × आय। आय = 12,600 ÷ 0.42 = ₹30,000। 20 + 30 + 25 = 75% को पूरी आय में से घटाने पर आम भूल वाला उत्तर ₹50,400 आता है।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-36","question":"The length of a rectangle is increased by 25%. By what percent must the breadth be cut to keep the area unchanged, and what happens to the area if the breadth is cut by only 10%?","options":["25%; area rises by 15%","20%; area rises by 15%","20%; area rises by 12.5%","25%; area rises by 12.5%"],"answer":2,"explanation":"For equal area, breadth factor = 1/1.25 = 0.8, a 20% cut. With a 10% cut, area factor = 1.25 × 0.9 = 1.125, a 12.5% increase. 25% − 10% = 15% is the additive slip.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"एक आयत की लंबाई 25% बढ़ा दी जाती है। क्षेत्रफल अपरिवर्तित रखने के लिए चौड़ाई कितने प्रतिशत घटानी होगी, और यदि चौड़ाई केवल 10% घटाई जाए तो क्षेत्रफल का क्या होगा?","optionsHi":["25%; क्षेत्रफल 15% बढ़ेगा","20%; क्षेत्रफल 15% बढ़ेगा","20%; क्षेत्रफल 12.5% बढ़ेगा","25%; क्षेत्रफल 12.5% बढ़ेगा"],"explanationHi":"समान क्षेत्रफल के लिए चौड़ाई का गुणक = 1/1.25 = 0.8, अर्थात् 20% की कमी। 10% कमी पर क्षेत्रफल का गुणक = 1.25 × 0.9 = 1.125, यानी 12.5% की वृद्धि। 25% − 10% = 15% जोड़-घटाव वाली भूल है।","subtopic":"successive-change"},
  {"id":"quant-percentage-37","question":"How many of the following statements are correct? 1. If x is 25% more than y, then y is 20% less than x. 2. Successive increases of 10% and 20% equal a single increase of 30%. 3. If a price falls by 20%, consumption can rise by 20% with no change in spending. 4. 0.5% of 400 is 20.","options":["Only two","Only three","All four","Only one"],"answer":3,"explanation":"Only 1 is correct: y = x/1.25 = 0.8x. 2: 1.1 × 1.2 = 1.32, a 32% rise, not 30%. 3: 0.8 × 1.2 = 0.96, so spending falls 4% (a 25% rise is needed). 4: 0.5% of 400 = 2, not 20.","difficulty":"very-hard","source":"SSC CGL","questionHi":"निम्नलिखित में से कितने कथन सही हैं? 1. यदि x, y से 25% अधिक है, तो y, x से 20% कम है। 2. 10% और 20% की क्रमिक वृद्धि एक 30% की एकल वृद्धि के बराबर होती है। 3. यदि मूल्य 20% गिरता है, तो खपत 20% बढ़ सकती है और व्यय में कोई परिवर्तन नहीं होता। 4. 400 का 0.5% = 20 होता है।","optionsHi":["केवल दो","केवल तीन","चारों","केवल एक"],"explanationHi":"केवल 1 सही है: y = x/1.25 = 0.8x। 2: 1.1 × 1.2 = 1.32, अर्थात् 32% की वृद्धि, 30% नहीं। 3: 0.8 × 1.2 = 0.96, अतः व्यय 4% घटता है (25% की वृद्धि चाहिए)। 4: 400 का 0.5% = 2, 20 नहीं।","subtopic":"successive-change"},
  {"id":"quant-percentage-38","question":"A candidate needs 36% to pass. He scores 190 marks and fails by 26 marks. Another candidate scores 40% more marks than the first. By how many marks does the second candidate clear the pass mark?","options":["50","40","74","26"],"answer":0,"explanation":"Pass mark = 190 + 26 = 216 = 36% of maximum, so maximum = 600. Second candidate = 190 × 1.4 = 266. Margin = 266 − 216 = 50.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"एक परीक्षार्थी को उत्तीर्ण होने के लिए 36% चाहिए। वह 190 अंक पाता है और 26 अंकों से अनुत्तीर्ण हो जाता है। एक दूसरा परीक्षार्थी पहले से 40% अधिक अंक पाता है। दूसरा परीक्षार्थी उत्तीर्ण अंक से कितने अंक अधिक पाता है?","optionsHi":["50","40","74","26"],"explanationHi":"उत्तीर्ण अंक = 190 + 26 = 216 = पूर्णांक का 36%, अतः पूर्णांक = 600। दूसरे के अंक = 190 × 1.4 = 266। अंतर = 266 − 216 = 50।","subtopic":"marks-exams"},
  {"id":"quant-percentage-39","question":"What is 0.5% of 3,600?","options":["1.8","72","18","180"],"answer":2,"explanation":"0.5% = 0.5/100 = 1/200, so 3,600 ÷ 200 = 18. Reading 0.5% as 5% gives 180.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"3,600 का 0.5% कितना होता है?","optionsHi":["1.8","72","18","180"],"explanationHi":"0.5% = 0.5/100 = 1/200, अतः 3,600 ÷ 200 = 18। 0.5% को 5% पढ़ लेने पर 180 आता है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-40","question":"Which is greater: 30% of 70 or 70% of 30?","options":["30% of 70","70% of 30","Cannot be determined","Both are equal"],"answer":3,"explanation":"x% of y = xy/100 = y% of x, so both equal 21. 'Cannot be determined' is wrong because both values are fully given, and the swap of percent and base never changes the product.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"कौन-सा अधिक है: 70 का 30% या 30 का 70%?","optionsHi":["30% (70 का)","70% (30 का)","निर्धारित नहीं किया जा सकता","दोनों बराबर हैं"],"explanationHi":"x का y% = xy/100 = y का x%, अतः दोनों 21 के बराबर हैं। 'निर्धारित नहीं किया जा सकता' गलत है क्योंकि दोनों मान पूरी तरह दिए गए हैं, और प्रतिशत व आधार की अदला-बदली से गुणनफल कभी नहीं बदलता।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-41","question":"The fraction 5/16 expressed as a percentage is:","options":["31.25%","30.25%","31.5%","32.5%"],"answer":0,"explanation":"5/16 × 100 = 500/16 = 31.25% (1/16 = 6.25%, so 5/16 = 31.25%). 31.5% and 30.25% come from rounding or slipping a digit in the division.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"भिन्न 5/16 को प्रतिशत के रूप में व्यक्त करने पर प्राप्त होता है:","optionsHi":["31.25%","30.25%","31.5%","32.5%"],"explanationHi":"5/16 × 100 = 500/16 = 31.25% (1/16 = 6.25%, अतः 5/16 = 31.25%)। 31.5% और 30.25% भाग देने में पूर्णांक बनाने या अंक गलत लिखने से आते हैं।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-42","question":"The price of an appliance including 18% GST is ₹5,310. What is its price before GST?","options":["₹4,500","₹4,354.20","₹4,600","₹4,400"],"answer":0,"explanation":"Base × 1.18 = 5,310, so base = 5,310 ÷ 1.18 = ₹4,500. Taking 18% off ₹5,310 (₹4,354.20) is wrong because GST is 18% of the base, not of the final price.","difficulty":"moderate","source":"RRB NTPC · SSC CGL","questionHi":"18% GST सहित एक उपकरण का मूल्य ₹5,310 है। GST से पहले इसका मूल्य कितना है?","optionsHi":["₹4,500","₹4,354.20","₹4,600","₹4,400"],"explanationHi":"आधार × 1.18 = 5,310, अतः आधार = 5,310 ÷ 1.18 = ₹4,500। ₹5,310 में से 18% घटाना (₹4,354.20) गलत है, क्योंकि GST आधार मूल्य का 18% होता है, अंतिम मूल्य का नहीं।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-43","question":"A bank raises its interest rate from 8% to 10% per annum. By what percent has the interest rate increased?","options":["25%","20%","2%","10%"],"answer":0,"explanation":"The rise is 2 percentage points, which is 2/8 × 100 = 25% of the old rate. 2% confuses percentage points with percent.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"एक बैंक अपनी ब्याज दर 8% से बढ़ाकर 10% वार्षिक कर देता है। ब्याज दर में कितने प्रतिशत की वृद्धि हुई?","optionsHi":["25%","20%","2%","10%"],"explanationHi":"वृद्धि 2 प्रतिशत अंक है, जो पुरानी दर का 2/8 × 100 = 25% है। 2% में प्रतिशत अंक और प्रतिशत को एक समझ लेने की भूल है।","subtopic":"successive-change"},
  {"id":"quant-percentage-44","question":"Two numbers are 30% and 50% more than a third number. The first number is what percent of the second?","options":["80%","84 1/3%","60%","86 2/3%"],"answer":3,"explanation":"Take the third number as 100: the numbers are 130 and 150, and 130/150 × 100 = 86 2/3%. Subtracting 50 − 30 to say 80% ignores the different bases.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"दो संख्याएँ किसी तीसरी संख्या से क्रमशः 30% और 50% अधिक हैं। पहली संख्या दूसरी संख्या का कितना प्रतिशत है?","optionsHi":["80%","84 1/3%","60%","86 2/3%"],"explanationHi":"तीसरी संख्या 100 लें: संख्याएँ 130 और 150 हैं, और 130/150 × 100 = 86 2/3%। 50 − 30 घटाकर 80% निकालना अलग-अलग आधारों को अनदेखा करना है।","subtopic":"successive-change"},
  {"id":"quant-percentage-45","question":"If x% of 250 = 15% of 400 + 10% of 150, then x is:","options":["32","25","30","35"],"answer":2,"explanation":"15% of 400 = 60 and 10% of 150 = 15, so 2.5x = 75 and x = 30.","difficulty":"moderate","source":"RRB NTPC · SSC CGL","questionHi":"यदि 250 का x% = 400 का 15% + 150 का 10%, तो x है:","optionsHi":["32","25","30","35"],"explanationHi":"400 का 15% = 60 और 150 का 10% = 15, अतः 2.5x = 75 और x = 30।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-46","question":"A 60-litre mixture of milk and water contains 20% water. How much water must be added so that water becomes 25% of the new mixture?","options":["3 litres","6 litres","4 litres","5 litres"],"answer":2,"explanation":"Milk = 48 L stays fixed and must be 75% of the new mixture, so the new total is 48 ÷ 0.75 = 64 L; water added = 64 − 60 = 4 L. Adding 5% of 60 (3 L) ignores that the total also grows.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"दूध और पानी के 60 लीटर मिश्रण में 20% पानी है। कितना पानी और मिलाया जाए कि नए मिश्रण में पानी 25% हो जाए?","optionsHi":["3 लीटर","6 लीटर","4 लीटर","5 लीटर"],"explanationHi":"दूध = 48 L स्थिर रहता है और नए मिश्रण का 75% होना चाहिए, अतः नया कुल = 48 ÷ 0.75 = 64 L; मिलाया गया पानी = 64 − 60 = 4 L। 60 का 5% (3 L) जोड़ना इस बात को अनदेखा करता है कि कुल मात्रा भी बढ़ती है।","subtopic":"mixtures-concentration"},
  {"id":"quant-percentage-47","question":"When the numerator of a fraction is increased by 20% and its denominator is decreased by 10%, the fraction becomes 16/21. The original fraction is:","options":["4/7","5/7","2/3","3/7"],"answer":0,"explanation":"The fraction is multiplied by 1.2/0.9 = 4/3, so the original is 16/21 × 3/4 = 4/7.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"जब किसी भिन्न के अंश में 20% की वृद्धि और हर में 10% की कमी की जाती है, तो भिन्न 16/21 हो जाती है। मूल भिन्न है:","optionsHi":["4/7","5/7","2/3","3/7"],"explanationHi":"भिन्न 1.2/0.9 = 4/3 से गुणा हो जाती है, अतः मूल भिन्न = 16/21 × 3/4 = 4/7।","subtopic":"successive-change"},
  {"id":"quant-percentage-48","question":"Fresh grapes contain 90% water by weight, while dried grapes contain 20% water. How much dried grapes can be obtained from 40 kg of fresh grapes?","options":["8 kg","4 kg","5 kg","6 kg"],"answer":2,"explanation":"The pulp is 10% of 40 = 4 kg and forms 80% of the dried grapes, so dried weight = 4 ÷ 0.8 = 5 kg. 4 kg forgets the 20% water still left in the dried grapes.","difficulty":"hard","source":"SSC CGL Tier 2 · CDS","questionHi":"ताज़े अंगूरों में भार के अनुसार 90% पानी होता है, जबकि सूखे अंगूरों में 20% पानी होता है। 40 kg ताज़े अंगूरों से कितने सूखे अंगूर प्राप्त हो सकते हैं?","optionsHi":["8 kg","4 kg","5 kg","6 kg"],"explanationHi":"गूदा 40 का 10% = 4 kg है और यह सूखे अंगूरों का 80% होता है, अतः सूखे अंगूरों का भार = 4 ÷ 0.8 = 5 kg। 4 kg में यह भुला दिया गया है कि सूखे अंगूरों में अब भी 20% पानी रहता है।","subtopic":"mixtures-concentration"},
  {"id":"quant-percentage-49","question":"The length, breadth and height of a cuboid are changed by +20%, +10% and −25% respectively. Its volume:","options":["increases by 1%","remains unchanged","increases by 5%","decreases by 1%"],"answer":3,"explanation":"New volume factor = 1.2 × 1.1 × 0.75 = 0.99, a 1% decrease. Adding 20 + 10 − 25 = +5% is the classic slip; percentages multiply, they do not add.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक घनाभ की लंबाई, चौड़ाई और ऊँचाई में क्रमशः +20%, +10% और −25% का परिवर्तन किया जाता है। इसका आयतन:","optionsHi":["1% बढ़ेगा","अपरिवर्तित रहेगा","5% बढ़ेगा","1% घटेगा"],"explanationHi":"नया आयतन गुणक = 1.2 × 1.1 × 0.75 = 0.99, अर्थात् 1% की कमी। 20 + 10 − 25 = +5% जोड़ना एक आम भूल है; प्रतिशत गुणा होते हैं, जोड़े नहीं जाते।","subtopic":"successive-change"},
  {"id":"quant-percentage-50","question":"A family spends 60% of its budget on food and 40% on other items. Food prices rise by 15% and other prices by 10%. If the family buys the same quantities, by what percent does its total expenditure rise?","options":["13%","13.5%","25%","12.5%"],"answer":0,"explanation":"The rise is a weighted average: 0.6 × 15 + 0.4 × 10 = 9 + 4 = 13%. 12.5% is the simple average of 15 and 10, which ignores the weights.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक परिवार अपने बजट का 60% भोजन पर और 40% अन्य वस्तुओं पर खर्च करता है। भोजन के मूल्य 15% और अन्य वस्तुओं के मूल्य 10% बढ़ जाते हैं। यदि परिवार वही मात्राएँ खरीदता है, तो उसका कुल व्यय कितने प्रतिशत बढ़ता है?","optionsHi":["13%","13.5%","25%","12.5%"],"explanationHi":"वृद्धि एक भारित औसत है: 0.6 × 15 + 0.4 × 10 = 9 + 4 = 13%। 12.5%, 15 और 10 का साधारण औसत है, जिसमें भार को अनदेखा किया गया है।","subtopic":"price-consumption"},
  {"id":"quant-percentage-51","question":"If 60% of A equals 3/4 of B, and B is 20% of C, then A is what percent of C?","options":["30%","25%","20%","16%"],"answer":1,"explanation":"0.6A = 0.75B gives A = 1.25B, and B = 0.2C, so A = 1.25 × 0.2C = 0.25C, i.e. 25% of C.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि A का 60%, B के 3/4 के बराबर है, और B, C का 20% है, तो A, C का कितना प्रतिशत है?","optionsHi":["30%","25%","20%","16%"],"explanationHi":"0.6A = 0.75B से A = 1.25B, और B = 0.2C, अतः A = 1.25 × 0.2C = 0.25C, अर्थात् C का 25%।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-52","question":"Income tax is nil on the first ₹3 lakh of income, 5% on the next ₹4 lakh and 10% on everything above ₹7 lakh. A person pays ₹38,000 as tax. What is his income?","options":["₹8.2 lakh","₹9.6 lakh","₹8.8 lakh","₹7.6 lakh"],"answer":2,"explanation":"Tax on the ₹4 lakh slab = ₹20,000, leaving ₹18,000 at 10%, i.e. ₹1.8 lakh above ₹7 lakh. Income = 3 + 4 + 1.8 = ₹8.8 lakh.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"आय के पहले ₹3 लाख पर आयकर शून्य है, अगले ₹4 लाख पर 5% है और ₹7 लाख से ऊपर की प्रत्येक राशि पर 10% है। एक व्यक्ति ₹38,000 कर देता है। उसकी आय कितनी है?","optionsHi":["₹8.2 लाख","₹9.6 लाख","₹8.8 लाख","₹7.6 लाख"],"explanationHi":"₹4 लाख वाले स्लैब पर कर = ₹20,000, शेष ₹18,000 पर 10% की दर है, अर्थात् ₹7 लाख से ऊपर ₹1.8 लाख। आय = 3 + 4 + 1.8 = ₹8.8 लाख।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-53","question":"If x increases by 20% and y decreases by 20%, by what percent does x²y change?","options":["Increases by 12%","Increases by 15.2%","Increases by 4%","Decreases by 4%"],"answer":1,"explanation":"x²y is multiplied by 1.2² × 0.8 = 1.44 × 0.8 = 1.152, an increase of 15.2%. Ignoring the square gives 1.2 × 0.8 = 0.96, a 4% decrease.","difficulty":"hard","source":"SSC CGL Tier 2 · CDS","questionHi":"यदि x में 20% की वृद्धि और y में 20% की कमी हो, तो x²y में कितने प्रतिशत परिवर्तन होता है?","optionsHi":["12% की वृद्धि","15.2% की वृद्धि","4% की वृद्धि","4% की कमी"],"explanationHi":"x²y, 1.2² × 0.8 = 1.44 × 0.8 = 1.152 से गुणा हो जाता है, अर्थात् 15.2% की वृद्धि। वर्ग को अनदेखा करने पर 1.2 × 0.8 = 0.96, यानी 4% की कमी आती है।","subtopic":"successive-change"},
  {"id":"quant-percentage-54","question":"In an election between two candidates, the loser got 45% of the votes and lost by 3,000 votes. Had 2,000 voters switched from the winner to the loser, the result would have been:","options":["the loser wins by 2,000 votes","the loser wins by 500 votes","the winner still wins by 1,000 votes","the loser wins by 1,000 votes"],"answer":3,"explanation":"10% of the votes = 3,000, so 30,000 votes were cast: 16,500 and 13,500. After the switch: 14,500 and 15,500, so the former loser wins by 1,000. Each switched vote changes the margin by 2, so the margin moves by 4,000.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"दो उम्मीदवारों के बीच एक चुनाव में हारने वाले को 45% मत मिले और वह 3,000 मतों से हारा। यदि 2,000 मतदाता विजेता से हटकर हारने वाले के पक्ष में चले जाते, तो परिणाम होता:","optionsHi":["हारने वाला 2,000 मतों से जीतता","हारने वाला 500 मतों से जीतता","विजेता फिर भी 1,000 मतों से जीतता","हारने वाला 1,000 मतों से जीतता"],"explanationHi":"मतों का 10% = 3,000, अतः कुल 30,000 मत डाले गए: 16,500 और 13,500। बदलाव के बाद: 14,500 और 15,500, अतः पहले हारने वाला 1,000 मतों से जीतता है। हर बदला हुआ मत अंतर को 2 से बदलता है, इसलिए अंतर 4,000 खिसक जाता है।","subtopic":"election-votes"},
  {"id":"quant-percentage-55","question":"x is 20% of y and y is 25% of z. If z − x = 760, then y is:","options":["190","240","200","160"],"answer":2,"explanation":"x = 0.2 × 0.25z = 0.05z, so z − x = 0.95z = 760 and z = 800; y = 25% of 800 = 200.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"x, y का 20% है और y, z का 25% है। यदि z − x = 760, तो y है:","optionsHi":["190","240","200","160"],"explanationHi":"x = 0.2 × 0.25z = 0.05z, अतः z − x = 0.95z = 760 और z = 800; y = 800 का 25% = 200।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-56","question":"A student was asked to increase a number by 15% but decreased it by 15% instead. His answer was 54 less than the correct answer. What was the number?","options":["180","360","150","270"],"answer":0,"explanation":"The two answers differ by 15% + 15% = 30% of the number, so 0.3x = 54 and x = 180. Using only 15% gives 360.","difficulty":"hard","source":"RRB NTPC · SSC CGL","questionHi":"एक विद्यार्थी से किसी संख्या में 15% की वृद्धि करने को कहा गया, लेकिन उसने उसके बजाय 15% की कमी कर दी। उसका उत्तर सही उत्तर से 54 कम था। संख्या क्या थी?","optionsHi":["180","360","150","270"],"explanationHi":"दोनों उत्तरों में संख्या के 15% + 15% = 30% का अंतर है, अतः 0.3x = 54 और x = 180। केवल 15% लेने पर 360 आता है।","subtopic":"successive-change"},
  {"id":"quant-percentage-57","question":"How many of the following statements are correct?\n1. Successive increases of 20% and 30% equal a single increase of 56%.\n2. If a price falls by 20%, consumption must rise by 25% to keep expenditure unchanged.\n3. If A is 20% of B, then B is 400% more than A.\n4. A 10% increase in the radius of a circle increases its area by 21%.","options":["Only three","Only two","Only one","All four"],"answer":3,"explanation":"All four are true. 1: 1.2 × 1.3 = 1.56. 2: 20/80 = 25%. 3: B = 5A, i.e. 400% more than A. 4: 1.1² = 1.21, a 21% rise in area.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"निम्नलिखित में से कितने कथन सही हैं?\n1. 20% और 30% की क्रमिक वृद्धि एक 56% की एकल वृद्धि के बराबर होती है।\n2. यदि मूल्य 20% गिरता है, तो व्यय अपरिवर्तित रखने के लिए खपत 25% बढ़नी चाहिए।\n3. यदि A, B का 20% है, तो B, A से 400% अधिक है।\n4. किसी वृत्त की त्रिज्या में 10% की वृद्धि से उसके क्षेत्रफल में 21% की वृद्धि होती है।","optionsHi":["केवल तीन","केवल दो","केवल एक","चारों"],"explanationHi":"चारों सही हैं। 1: 1.2 × 1.3 = 1.56। 2: 20/80 = 25%। 3: B = 5A, अर्थात् A से 400% अधिक। 4: 1.1² = 1.21, क्षेत्रफल में 21% की वृद्धि।","subtopic":"successive-change"},
  {"id":"quant-percentage-58","question":"A town has a population of 1,20,000. Each year the population grows by 5% due to births and falls by 2% due to deaths, and 1,600 people emigrate at the end of each year. What is the population after 2 years?","options":["1,27,308","1,24,060","1,24,108","1,23,960"],"answer":1,"explanation":"Net growth is 3% a year. Year 1: 1,20,000 × 1.03 − 1,600 = 1,22,000. Year 2: 1,22,000 × 1.03 − 1,600 = 1,24,060. Subtracting 3,200 only at the end (1,24,108) forgets that the first year's emigrants do not grow.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक कस्बे की जनसंख्या 1,20,000 है। प्रत्येक वर्ष जन्म के कारण जनसंख्या 5% बढ़ती है और मृत्यु के कारण 2% घटती है, तथा प्रत्येक वर्ष के अंत में 1,600 लोग प्रवास कर जाते हैं। 2 वर्ष बाद जनसंख्या कितनी होगी?","optionsHi":["1,27,308","1,24,060","1,24,108","1,23,960"],"explanationHi":"शुद्ध वृद्धि प्रतिवर्ष 3% है। वर्ष 1: 1,20,000 × 1.03 − 1,600 = 1,22,000। वर्ष 2: 1,22,000 × 1.03 − 1,600 = 1,24,060। 3,200 को केवल अंत में घटाना (1,24,108) यह भुला देता है कि पहले वर्ष के प्रवासी लोगों पर वृद्धि नहीं होती।","subtopic":"population-depreciation"},
  {"id":"quant-percentage-59","question":"In an election among three candidates, 20% of the votes cast were invalid. The winner got 50% of the valid votes, the runner-up got 60% of the remaining valid votes and the third candidate got 4,800 votes. How many votes were cast in all?","options":["32,000","30,000","28,800","24,000"],"answer":1,"explanation":"The third candidate got 40% of the remaining 50%, i.e. 20% of valid votes = 4,800, so valid votes = 24,000. These are 80% of votes cast, so votes cast = 24,000 ÷ 0.8 = 30,000. 24,000 stops at the valid votes.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"तीन उम्मीदवारों के बीच एक चुनाव में डाले गए मतों में से 20% अवैध थे। विजेता को वैध मतों का 50% मिला, उपविजेता को शेष वैध मतों का 60% मिला और तीसरे उम्मीदवार को 4,800 मत मिले। कुल कितने मत डाले गए?","optionsHi":["32,000","30,000","28,800","24,000"],"explanationHi":"तीसरे उम्मीदवार को शेष 50% का 40%, अर्थात् वैध मतों का 20% = 4,800 मिला, अतः वैध मत = 24,000। ये डाले गए मतों का 80% हैं, अतः डाले गए मत = 24,000 ÷ 0.8 = 30,000। 24,000 केवल वैध मतों तक ही रुक जाता है।","subtopic":"election-votes"},
  {"id":"quant-percentage-60","question":"A test has three papers with maximum marks 100, 150 and 250. A student scores 60% in the first paper and 70% in the second. What percent must he score in the third paper to get 72% overall?","options":["80%","75%","78%","86%"],"answer":2,"explanation":"He needs 72% of 500 = 360 marks; he has 60 + 105 = 165, so he needs 195 of 250 = 78%. 86% comes from averaging percentages (3 × 72 − 60 − 70), which ignores the unequal maximum marks.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"एक परीक्षा में तीन प्रश्नपत्र हैं जिनके पूर्णांक 100, 150 और 250 हैं। एक विद्यार्थी पहले प्रश्नपत्र में 60% और दूसरे में 70% अंक पाता है। कुल मिलाकर 72% अंक पाने के लिए उसे तीसरे प्रश्नपत्र में कितने प्रतिशत अंक पाने होंगे?","optionsHi":["80%","75%","78%","86%"],"explanationHi":"उसे 500 के 72% = 360 अंक चाहिए; उसके पास 60 + 105 = 165 हैं, अतः उसे 250 में से 195 = 78% चाहिए। 86% प्रतिशतों का औसत लेने (3 × 72 − 60 − 70) से आता है, जो असमान पूर्णांकों को अनदेखा करता है।","subtopic":"marks-exams"},
  {"id":"quant-percentage-61","question":"A's income is 20% more than B's. A saves 25% of his income and B saves 15% of his. If A's expenditure exceeds B's by ₹3,600, what is B's income?","options":["₹60,000","₹72,000","₹80,000","₹48,000"],"answer":1,"explanation":"Let B's income be x. A's expenditure = 0.75 × 1.2x = 0.9x and B's = 0.85x, so 0.05x = 3,600 and x = ₹72,000.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"A की आय B की आय से 20% अधिक है। A अपनी आय का 25% और B अपनी आय का 15% बचाता है। यदि A का व्यय B के व्यय से ₹3,600 अधिक है, तो B की आय कितनी है?","optionsHi":["₹60,000","₹72,000","₹80,000","₹48,000"],"explanationHi":"माना B की आय x है। A का व्यय = 0.75 × 1.2x = 0.9x और B का = 0.85x, अतः 0.05x = 3,600 और x = ₹72,000।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-62","question":"In a town the male population rises by 5% and the female population by 8%, and the total population rises by 6.2%. What was the ratio of males to females originally?","options":["3 : 4","3 : 2","4 : 3","2 : 3"],"answer":1,"explanation":"5m + 8f = 6.2(m + f) gives 1.8f = 1.2m, so m : f = 1.8 : 1.2 = 3 : 2. (Alligation: (8 − 6.2) : (6.2 − 5) = 1.8 : 1.2.)","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक कस्बे में पुरुष जनसंख्या 5% और महिला जनसंख्या 8% बढ़ती है, तथा कुल जनसंख्या 6.2% बढ़ती है। पुरुषों और महिलाओं का मूल अनुपात क्या था?","optionsHi":["3 : 4","3 : 2","4 : 3","2 : 3"],"explanationHi":"5m + 8f = 6.2(m + f) से 1.8f = 1.2m, अतः m : f = 1.8 : 1.2 = 3 : 2। (एलीगेशन: (8 − 6.2) : (6.2 − 5) = 1.8 : 1.2।)","subtopic":"population-depreciation"},
  {"id":"quant-percentage-63","question":"A phone's base price is ₹50,000 and GST of 28% is charged on it. In a sale, the base price is cut by 10% and the GST rate is reduced to 18%. How much does a buyer save on the final price?","options":["₹6,400","₹10,900","₹12,800","₹9,900"],"answer":1,"explanation":"Before: 50,000 × 1.28 = ₹64,000. After: 45,000 × 1.18 = ₹53,100. Saving = ₹10,900. Taking 20% off ₹64,000 (₹12,800) wrongly adds the 10% cut to the 10-point GST change.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक फोन का आधार मूल्य ₹50,000 है और उस पर 28% GST लगता है। एक सेल में आधार मूल्य 10% घटा दिया जाता है और GST की दर घटाकर 18% कर दी जाती है। खरीदार को अंतिम मूल्य पर कितनी बचत होती है?","optionsHi":["₹6,400","₹10,900","₹12,800","₹9,900"],"explanationHi":"पहले: 50,000 × 1.28 = ₹64,000। बाद में: 45,000 × 1.18 = ₹53,100। बचत = ₹10,900। ₹64,000 पर 20% की छूट लेना (₹12,800) गलत है, क्योंकि इसमें 10% की कटौती को GST के 10 अंकों के परिवर्तन के साथ जोड़ दिया गया है।","subtopic":"successive-change"},
  {"id":"quant-percentage-64","question":"A 50-litre solution contains 40% alcohol. x litres are drawn off and replaced with water, and the process is repeated once more. The solution now contains 25.6% alcohol. What is x?","options":["8","15","12","10"],"answer":3,"explanation":"0.4(1 − x/50)² = 0.256, so (1 − x/50)² = 0.64, 1 − x/50 = 0.8 and x = 10.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"50 लीटर के घोल में 40% अल्कोहल है। x लीटर घोल निकालकर उसकी जगह पानी मिला दिया जाता है, और यह प्रक्रिया एक बार और दोहराई जाती है। अब घोल में 25.6% अल्कोहल है। x क्या है?","optionsHi":["8","15","12","10"],"explanationHi":"0.4(1 − x/50)² = 0.256, अतः (1 − x/50)² = 0.64, 1 − x/50 = 0.8 और x = 10।","subtopic":"mixtures-concentration"},
  {"id":"quant-percentage-65","question":"In a town of 50,000 people, 40% read newspaper A, 35% read B and 25% read C; 10% read A and B, 8% read B and C, 7% read A and C, and 3% read all three. How many people read none of the three?","options":["11,000","9,500","12,500","14,000"],"answer":0,"explanation":"At least one = 40 + 35 + 25 − 10 − 8 − 7 + 3 = 78%, so none = 22% of 50,000 = 11,000. Forgetting to add back the 3% gives 25% = 12,500.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"50,000 की आबादी वाले एक कस्बे में 40% लोग समाचार पत्र A, 35% B और 25% C पढ़ते हैं; 10% A और B, 8% B और C, 7% A और C, तथा 3% तीनों पढ़ते हैं। कितने लोग तीनों में से कोई भी नहीं पढ़ते?","optionsHi":["11,000","9,500","12,500","14,000"],"explanationHi":"कम से कम एक = 40 + 35 + 25 − 10 − 8 − 7 + 3 = 78%, अतः कोई नहीं = 50,000 का 22% = 11,000। 3% जोड़ना भूल जाने पर 25% = 12,500 आता है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-66","question":"The radius of a sphere is increased by 10%. If its surface area increases by x% and its volume by y%, what is y − x?","options":["10","12.1","12","9"],"answer":1,"explanation":"Surface area ∝ r²: 1.1² = 1.21, so x = 21. Volume ∝ r³: 1.1³ = 1.331, so y = 33.1. y − x = 12.1.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"एक गोले की त्रिज्या 10% बढ़ा दी जाती है। यदि उसके पृष्ठीय क्षेत्रफल में x% और आयतन में y% की वृद्धि होती है, तो y − x क्या है?","optionsHi":["10","12.1","12","9"],"explanationHi":"पृष्ठीय क्षेत्रफल ∝ r²: 1.1² = 1.21, अतः x = 21। आयतन ∝ r³: 1.1³ = 1.331, अतः y = 33.1। y − x = 12.1।","subtopic":"successive-change"},
  {"id":"quant-percentage-67","question":"Assertion (A): If the price of an article falls by one-fifth, a buyer can increase his consumption by one-fourth without changing his expenditure.\nReason (R): After a decrease of x%, quantity must rise by 100x/(100 − x)% to keep expenditure constant.","options":["A is false but R is true","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"A fall of 1/5 = 20%, and by R the rise needed is 100 × 20/80 = 25% = 1/4. R is exactly the rule that proves A.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"अभिकथन (A): यदि किसी वस्तु का मूल्य एक-पाँचवाँ भाग गिर जाए, तो खरीदार अपना व्यय बदले बिना खपत एक-चौथाई बढ़ा सकता है।\nकारण (R): x% की कमी के बाद, व्यय स्थिर रखने के लिए मात्रा 100x/(100 − x)% बढ़नी चाहिए।","optionsHi":["A गलत है लेकिन R सही है","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है","A सही है लेकिन R गलत है","A और R दोनों सही हैं, और R, A की सही व्याख्या है"],"explanationHi":"1/5 की गिरावट = 20%, और R के अनुसार आवश्यक वृद्धि = 100 × 20/80 = 25% = 1/4। R ठीक वही नियम है जो A को सिद्ध करता है।","subtopic":"price-consumption"},
  {"id":"quant-percentage-68","question":"A test has 200 questions, with +1 for a correct answer and −0.25 for a wrong one. A student attempts 80% of the questions and scores 50% of the maximum marks. What percent of his attempted questions were correct?","options":["56%","62.5%","75%","70%"],"answer":3,"explanation":"He attempts 160 and scores 100: c − 0.25(160 − c) = 100, so 1.25c = 140 and c = 112. Accuracy = 112/160 = 70%. 56% divides 112 by all 200 questions.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक परीक्षा में 200 प्रश्न हैं, सही उत्तर के लिए +1 और गलत उत्तर के लिए −0.25 अंक हैं। एक विद्यार्थी 80% प्रश्न हल करता है और अधिकतम अंकों का 50% पाता है। उसके हल किए गए प्रश्नों में से कितने प्रतिशत सही थे?","optionsHi":["56%","62.5%","75%","70%"],"explanationHi":"वह 160 हल करता है और 100 अंक पाता है: c − 0.25(160 − c) = 100, अतः 1.25c = 140 और c = 112। शुद्धता = 112/160 = 70%। 56% में 112 को सभी 200 प्रश्नों से भाग दिया गया है।","subtopic":"marks-exams"},
  {"id":"quant-percentage-69","question":"If 125% of a number is 450, what is 80% of the same number?","options":["360","288","300","270"],"answer":1,"explanation":"The number is 450 ÷ 1.25 = 360, and 80% of 360 = 288. Shortcut: 80% ÷ 125% = 0.64, so 0.64 × 450 = 288.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"यदि किसी संख्या का 125% = 450, तो उसी संख्या का 80% कितना है?","optionsHi":["360","288","300","270"],"explanationHi":"संख्या = 450 ÷ 1.25 = 360, और 360 का 80% = 288। शॉर्टकट: 80% ÷ 125% = 0.64, अतः 0.64 × 450 = 288।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-70","question":"Which of the following is the largest: 7/8, 85%, 0.86, 17/20?","options":["7/8","85%","0.86","17/20"],"answer":0,"explanation":"Convert all to decimals: 7/8 = 0.875, 85% = 0.85, 0.86 and 17/20 = 0.85. The largest is 7/8.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"निम्नलिखित में से सबसे बड़ा कौन-सा है: 7/8, 85%, 0.86, 17/20?","optionsHi":["7/8","85%","0.86","17/20"],"explanationHi":"सभी को दशमलव में बदलें: 7/8 = 0.875, 85% = 0.85, 0.86 और 17/20 = 0.85। सबसे बड़ा 7/8 है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-71","question":"Suresh's monthly salary of ₹48,000 is raised by 15%, and then 10% of the new salary is deducted towards his provident fund. What is his take-home salary now?","options":["₹50,400","₹49,200","₹52,800","₹49,680"],"answer":3,"explanation":"Take-home = 48,000 × 1.15 × 0.9 = 48,000 × 1.035 = ₹49,680. Netting +15% and −10% as +5% (₹50,400) is the trap.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk","questionHi":"सुरेश के ₹48,000 के मासिक वेतन में 15% की वृद्धि की जाती है, और फिर नए वेतन का 10% भविष्य निधि के लिए काट लिया जाता है। उसका अब हाथ में आने वाला वेतन कितना है?","optionsHi":["₹50,400","₹49,200","₹52,800","₹49,680"],"explanationHi":"हाथ में आने वाला वेतन = 48,000 × 1.15 × 0.9 = 48,000 × 1.035 = ₹49,680। +15% और −10% को +5% (₹50,400) मान लेना जाल है।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-72","question":"In a school, 45% of the students are girls. If 165 boys are absent on a day and they make up 25% of all the boys, what is the total strength of the school?","options":["1,100","1,320","1,200","1,500"],"answer":2,"explanation":"Boys = 165 ÷ 0.25 = 660, which is 55% of the strength. Total = 660 ÷ 0.55 = 1,200.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"एक विद्यालय में 45% विद्यार्थी लड़कियाँ हैं। यदि किसी दिन 165 लड़के अनुपस्थित हैं और वे सभी लड़कों का 25% हैं, तो विद्यालय की कुल संख्या कितनी है?","optionsHi":["1,100","1,320","1,200","1,500"],"explanationHi":"लड़के = 165 ÷ 0.25 = 660, जो कुल संख्या का 55% है। कुल = 660 ÷ 0.55 = 1,200।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-73","question":"By what percent is 3/5 of 2/3 of a number less than 4/5 of the same number?","options":["40%","100%","50%","25%"],"answer":2,"explanation":"3/5 × 2/3 = 2/5, which is half of 4/5. So it is 50% less. 100% is the answer to 'by what percent is 4/5 more'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"किसी संख्या का 2/3 का 3/5, उसी संख्या के 4/5 से कितने प्रतिशत कम है?","optionsHi":["40%","100%","50%","25%"],"explanationHi":"3/5 × 2/3 = 2/5, जो 4/5 का आधा है। अतः यह 50% कम है। 100% तो 'कि 4/5 कितने प्रतिशत अधिक है' का उत्तर है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-74","question":"A television is listed at ₹40,000. Shop P gives a 10% discount and then charges 18% GST on the discounted price. Shop Q adds 18% GST to the list price and then gives a 12% discount on the bill. How much more does Shop P charge than Shop Q?","options":["₹1,180","₹944","₹800","₹472"],"answer":1,"explanation":"P: 40,000 × 0.9 × 1.18 = ₹42,480. Q: 40,000 × 1.18 × 0.88 = ₹41,536. Difference = 40,000 × 1.18 × 0.02 = ₹944 — the order of discount and GST does not matter, only the discount rates do.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक टेलीविज़न का सूचीबद्ध मूल्य ₹40,000 है। दुकान P 10% की छूट देती है और फिर छूट के बाद के मूल्य पर 18% GST लगाती है। दुकान Q सूचीबद्ध मूल्य पर 18% GST जोड़ती है और फिर बिल पर 12% की छूट देती है। दुकान P, दुकान Q से कितना अधिक लेती है?","optionsHi":["₹1,180","₹944","₹800","₹472"],"explanationHi":"P: 40,000 × 0.9 × 1.18 = ₹42,480। Q: 40,000 × 1.18 × 0.88 = ₹41,536। अंतर = 40,000 × 1.18 × 0.02 = ₹944 — छूट और GST का क्रम मायने नहीं रखता, केवल छूट की दरें मायने रखती हैं।","subtopic":"successive-change"},
  {"id":"quant-percentage-75","question":"A panchayat ward has 25,000 voters. 10% of them did not vote, and 4% of the votes cast were invalid. In a two-candidate contest the winner got 55% of the valid votes. By how many votes did he win?","options":["2,160","2,250","2,500","2,025"],"answer":0,"explanation":"Valid votes = 25,000 × 0.9 × 0.96 = 21,600. Margin = (55 − 45)% of valid votes = 10% of 21,600 = 2,160. Taking 10% of votes cast (2,250) forgets the invalid votes.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक पंचायत वार्ड में 25,000 मतदाता हैं। उनमें से 10% ने मतदान नहीं किया, और डाले गए मतों में से 4% अवैध थे। दो उम्मीदवारों की प्रतिस्पर्धा में विजेता को वैध मतों का 55% मिला। वह कितने मतों से जीता?","optionsHi":["2,160","2,250","2,500","2,025"],"explanationHi":"वैध मत = 25,000 × 0.9 × 0.96 = 21,600। अंतर = वैध मतों का (55 − 45)% = 21,600 का 10% = 2,160। डाले गए मतों का 10% (2,250) लेने में अवैध मतों को भुला दिया गया है।","subtopic":"election-votes"},
  {"id":"quant-percentage-76","question":"The price of mustard oil rose by 25% in April and by a further x% in May. If the total rise over the two months is 50%, what is x?","options":["25","22.5","30","20"],"answer":3,"explanation":"1.25 × (1 + x/100) = 1.5, so 1 + x/100 = 1.2 and x = 20. Subtracting 50 − 25 = 25 ignores that May's rise is on a larger base.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"सरसों के तेल का मूल्य अप्रैल में 25% और मई में x% और बढ़ गया। यदि दोनों महीनों में कुल वृद्धि 50% है, तो x क्या है?","optionsHi":["25","22.5","30","20"],"explanationHi":"1.25 × (1 + x/100) = 1.5, अतः 1 + x/100 = 1.2 और x = 20। 50 − 25 = 25 घटाना इस बात को अनदेखा करता है कि मई की वृद्धि बड़े आधार पर होती है।","subtopic":"successive-change"},
  {"id":"quant-percentage-77","question":"In a recruitment test, Anil scores 30% more than Bimal, and Chitra scores 20% less than Anil. If Chitra scores 6 marks more than Bimal, what is Anil's score?","options":["150","156","180","195"],"answer":3,"explanation":"Chitra = 1.3 × 0.8 = 1.04 of Bimal, so 4% of Bimal = 6 and Bimal = 150. Anil = 1.3 × 150 = 195.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक भर्ती परीक्षा में अनिल के अंक बिमल से 30% अधिक हैं, और चित्रा के अंक अनिल से 20% कम हैं। यदि चित्रा के अंक बिमल से 6 अधिक हैं, तो अनिल के अंक कितने हैं?","optionsHi":["150","156","180","195"],"explanationHi":"चित्रा = 1.3 × 0.8 = बिमल का 1.04, अतः बिमल का 4% = 6 और बिमल = 150। अनिल = 1.3 × 150 = 195।","subtopic":"successive-change"},
  {"id":"quant-percentage-78","question":"A town had a population of 2,40,000 in 2023. It rose by 5% in 2024, fell by 5% in 2025 and rose by 10% in 2026. What was the population at the end of 2026?","options":["2,64,000","2,63,000","2,63,340","2,62,500"],"answer":2,"explanation":"2,40,000 × 1.05 × 0.95 × 1.1. Note 1.05 × 0.95 = 0.9975 (not 1), so the answer is 2,64,000 × 0.9975 = 2,63,340.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"एक कस्बे की जनसंख्या 2023 में 2,40,000 थी। 2024 में यह 5% बढ़ी, 2025 में 5% घटी और 2026 में 10% बढ़ी। 2026 के अंत में जनसंख्या कितनी थी?","optionsHi":["2,64,000","2,63,000","2,63,340","2,62,500"],"explanationHi":"2,40,000 × 1.05 × 0.95 × 1.1। ध्यान दें 1.05 × 0.95 = 0.9975 (1 नहीं), अतः उत्तर = 2,64,000 × 0.9975 = 2,63,340।","subtopic":"population-depreciation"},
  {"id":"quant-percentage-79","question":"After a 20% fall in the price of sugar, a household buys 6 kg more than it used to buy for ₹1,200 and still spends ₹120 less than ₹1,200. What is the new price of sugar per kg?","options":["₹25","₹20","₹18","₹22.50"],"answer":1,"explanation":"Let the old price be p, so old quantity = 1,200/p. New spend = 0.8p × (1,200/p + 6) = 960 + 4.8p = 1,080, giving p = 25. New price = 0.8 × 25 = ₹20.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"चीनी के मूल्य में 20% की गिरावट के बाद एक परिवार पहले ₹1,200 में जितनी चीनी खरीदता था उससे 6 kg अधिक खरीदता है और फिर भी ₹1,200 से ₹120 कम खर्च करता है। चीनी का नया मूल्य प्रति kg कितना है?","optionsHi":["₹25","₹20","₹18","₹22.50"],"explanationHi":"माना पुराना मूल्य p है, अतः पुरानी मात्रा = 1,200/p। नया व्यय = 0.8p × (1,200/p + 6) = 960 + 4.8p = 1,080, जिससे p = 25। नया मूल्य = 0.8 × 25 = ₹20।","subtopic":"price-consumption"},
  {"id":"quant-percentage-80","question":"A is 25% more than B, B is 40% less than C, and C exceeds A by 60. What is B?","options":["144","180","150","120"],"answer":0,"explanation":"B = 0.6C and A = 1.25 × 0.6C = 0.75C. C − A = 0.25C = 60, so C = 240 and B = 0.6 × 240 = 144.","difficulty":"hard","source":"SSC CGL · SSC CPO","questionHi":"A, B से 25% अधिक है, B, C से 40% कम है, और C, A से 60 अधिक है। B कितना है?","optionsHi":["144","180","150","120"],"explanationHi":"B = 0.6C और A = 1.25 × 0.6C = 0.75C। C − A = 0.25C = 60, अतः C = 240 और B = 0.6 × 240 = 144।","subtopic":"successive-change"},
  {"id":"quant-percentage-81","question":"A hospital has 40 litres of a sanitiser that is 70% alcohol. How much water must be added to bring the alcohol content down to 56%?","options":["10 litres","8 litres","12 litres","14 litres"],"answer":0,"explanation":"Alcohol stays at 28 L. For 56%, the total must be 28 ÷ 0.56 = 50 L, so add 10 L of water.","difficulty":"moderate","source":"SSC CHSL · RRB Group D","questionHi":"एक अस्पताल के पास 40 लीटर सैनिटाइज़र है जिसमें 70% अल्कोहल है। अल्कोहल की मात्रा 56% करने के लिए कितना पानी मिलाना होगा?","optionsHi":["10 लीटर","8 लीटर","12 लीटर","14 लीटर"],"explanationHi":"अल्कोहल 28 L ही रहता है। 56% के लिए कुल मात्रा 28 ÷ 0.56 = 50 L होनी चाहिए, अतः 10 L पानी मिलाना होगा।","subtopic":"mixtures-concentration"},
  {"id":"quant-percentage-82","question":"Neha pays 30% of her salary as rent, spends 20% of the rest on groceries and 25% of what then remains on a loan EMI. She saves the remaining ₹25,200. How much is her EMI?","options":["₹9,000","₹7,560","₹10,500","₹8,400"],"answer":3,"explanation":"Savings = 0.7 × 0.8 × 0.75 = 0.42 of salary, so salary = ₹60,000. EMI = 0.7 × 0.8 × 0.25 × 60,000 = ₹8,400 (one-third of the savings, since 25 : 75 = 1 : 3).","difficulty":"hard","source":"IBPS Clerk · SBI Clerk","questionHi":"नेहा अपने वेतन का 30% किराये में देती है, शेष का 20% किराने पर खर्च करती है और उसके बाद बचे हुए का 25% ऋण की EMI पर खर्च करती है। बाकी ₹25,200 वह बचा लेती है। उसकी EMI कितनी है?","optionsHi":["₹9,000","₹7,560","₹10,500","₹8,400"],"explanationHi":"बचत = 0.7 × 0.8 × 0.75 = वेतन का 0.42, अतः वेतन = ₹60,000। EMI = 0.7 × 0.8 × 0.25 × 60,000 = ₹8,400 (बचत का एक-तिहाई, क्योंकि 25 : 75 = 1 : 3)।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-83","question":"A state's unemployment rate fell from 8% to 6% in a year. By what percent did the unemployment rate fall?","options":["2%","33.33%","25%","20%"],"answer":2,"explanation":"The fall is 2 percentage points, but as a percent of the old rate it is 2/8 × 100 = 25%. '2%' confuses percentage points with percent.","difficulty":"moderate","source":"SSC CGL · RBI Assistant","questionHi":"एक राज्य में बेरोज़गारी दर एक वर्ष में 8% से घटकर 6% हो गई। बेरोज़गारी दर में कितने प्रतिशत की कमी हुई?","optionsHi":["2%","33.33%","25%","20%"],"explanationHi":"कमी 2 प्रतिशत अंक है, लेकिन पुरानी दर के प्रतिशत के रूप में यह 2/8 × 100 = 25% है। '2%' में प्रतिशत अंक और प्रतिशत को एक समझ लिया गया है।","subtopic":"successive-change"},
  {"id":"quant-percentage-84","question":"If x% of x is 36, what is x?","options":["6","60","36","600"],"answer":1,"explanation":"x × x/100 = 36, so x² = 3,600 and x = 60. 6 solves x² = 36, forgetting the /100, and 600 adds an extra zero.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"यदि x का x% = 36, तो x क्या है?","optionsHi":["6","60","36","600"],"explanationHi":"x × x/100 = 36, अतः x² = 3,600 और x = 60। 6, x² = 36 को हल करता है जिसमें /100 भुला दिया गया है, और 600 में एक अतिरिक्त शून्य जोड़ दिया गया है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-85","question":"A number increased by 37.5% becomes 165. What does it become if it is instead decreased by 12.5%?","options":["120","105","144.375","110"],"answer":1,"explanation":"37.5% = 3/8, so the number = 165 × 8/11 = 120. Decreasing by 12.5% (1/8): 120 × 7/8 = 105.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"किसी संख्या में 37.5% की वृद्धि करने पर वह 165 हो जाती है। यदि उसमें इसके बजाय 12.5% की कमी की जाए तो वह क्या हो जाएगी?","optionsHi":["120","105","144.375","110"],"explanationHi":"37.5% = 3/8, अतः संख्या = 165 × 8/11 = 120। 12.5% (1/8) घटाने पर: 120 × 7/8 = 105।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-86","question":"A trader stores 1,000 kg of watermelons that are 99% water by weight. After a few days in the sun they are 98% water. What do they weigh now?","options":["500 kg","990 kg","980 kg","900 kg"],"answer":0,"explanation":"Dry matter = 1% of 1,000 = 10 kg and does not change. Now it is 2% of the weight, so weight = 10 ÷ 0.02 = 500 kg. A 1-point drop in water halves the weight.","difficulty":"very-hard","source":"SSC CGL · CAT-style","questionHi":"एक व्यापारी 1,000 kg तरबूज़ रखता है जिनमें भार के अनुसार 99% पानी है। कुछ दिन धूप में रहने के बाद उनमें 98% पानी रह जाता है। अब उनका भार कितना है?","optionsHi":["500 kg","990 kg","980 kg","900 kg"],"explanationHi":"शुष्क पदार्थ = 1,000 का 1% = 10 kg, जो नहीं बदलता। अब यह भार का 2% है, अतः भार = 10 ÷ 0.02 = 500 kg। पानी में 1 अंक की कमी से भार आधा हो जाता है।","subtopic":"mixtures-concentration"},
  {"id":"quant-percentage-87","question":"On a voters' list, 30% of the voters are women. If 80% of the men and 60% of the women cast their votes, what percentage of the voters on the list voted?","options":["70%","72%","76%","74%"],"answer":3,"explanation":"Weighted: 0.7 × 80 + 0.3 × 60 = 56 + 18 = 74%. The plain average of 80 and 60 (70%) ignores that there are more men.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk","questionHi":"एक मतदाता सूची में 30% मतदाता महिलाएँ हैं। यदि 80% पुरुष और 60% महिलाएँ मतदान करती हैं, तो सूची के कितने प्रतिशत मतदाताओं ने मतदान किया?","optionsHi":["70%","72%","76%","74%"],"explanationHi":"भारित औसत: 0.7 × 80 + 0.3 × 60 = 56 + 18 = 74%। 80 और 60 का साधारण औसत (70%) इस बात को अनदेखा करता है कि पुरुष अधिक हैं।","subtopic":"election-votes"},
  {"id":"quant-percentage-88","question":"A's salary is 40% of B's and B's salary is 75% of C's. If the three together earn ₹82,000, what is A's salary?","options":["₹30,000","₹16,000","₹12,000","₹15,000"],"answer":2,"explanation":"With C = 100: B = 75 and A = 40% of 75 = 30. Total = 205 parts = ₹82,000, so one part = 400 and A = 30 × 400 = ₹12,000.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"A का वेतन B के वेतन का 40% है और B का वेतन C के वेतन का 75% है। यदि तीनों मिलकर ₹82,000 कमाते हैं, तो A का वेतन कितना है?","optionsHi":["₹30,000","₹16,000","₹12,000","₹15,000"],"explanationHi":"C = 100 लें: B = 75 और A = 75 का 40% = 30। कुल = 205 भाग = ₹82,000, अतः एक भाग = 400 और A = 30 × 400 = ₹12,000।","subtopic":"successive-change"},
  {"id":"quant-percentage-89","question":"A single increase equivalent to three successive increases of 10%, 20% and 30% is:","options":["60%","66%","71.6%","72.6%"],"answer":2,"explanation":"1.1 × 1.2 × 1.3 = 1.716, i.e. a 71.6% increase. Adding the rates (60%) ignores the compounding.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"10%, 20% और 30% की तीन क्रमिक वृद्धियों के समतुल्य एकल वृद्धि है:","optionsHi":["60%","66%","71.6%","72.6%"],"explanationHi":"1.1 × 1.2 × 1.3 = 1.716, अर्थात् 71.6% की वृद्धि। दरों को जोड़ना (60%) चक्रवृद्धि प्रभाव को अनदेखा करता है।","subtopic":"successive-change"},
  {"id":"quant-percentage-90","question":"In a factory 60% of the workers are skilled and earn ₹800 a day, while the rest earn ₹500 a day. If skilled wages rise by 5% and unskilled wages by 20%, by about what percent does the daily wage bill rise?","options":["11%","9.4%","12.5%","8.6%"],"answer":1,"explanation":"Per 10 workers: bill = 6 × 800 + 4 × 500 = ₹6,800. Rise = 6 × 40 + 4 × 100 = ₹640, and 640/6,800 ≈ 9.4%. Averaging 5% and 20% by headcount (11%) forgets the different wages.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"एक कारखाने में 60% कामगार कुशल हैं और ₹800 प्रतिदिन कमाते हैं, जबकि शेष ₹500 प्रतिदिन कमाते हैं। यदि कुशल कामगारों की मज़दूरी 5% और अकुशल कामगारों की 20% बढ़ जाए, तो दैनिक मज़दूरी बिल लगभग कितने प्रतिशत बढ़ता है?","optionsHi":["11%","9.4%","12.5%","8.6%"],"explanationHi":"प्रति 10 कामगार: बिल = 6 × 800 + 4 × 500 = ₹6,800। वृद्धि = 6 × 40 + 4 × 100 = ₹640, और 640/6,800 ≈ 9.4%। 5% और 20% का कामगारों की संख्या के अनुसार औसत (11%) लेना अलग-अलग मज़दूरी को भुला देता है।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-91","question":"A's salary rises by 20% every year (on the previous year's salary). B starts ₹10,000 above A and gets a fixed raise of ₹6,000 every year. After two years their salaries are equal. What was A's starting salary?","options":["₹50,000","₹55,000","₹45,000","₹60,000"],"answer":0,"explanation":"After 2 years A has 1.44A and B has A + 10,000 + 12,000. So 0.44A = 22,000 and A = ₹50,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"A का वेतन हर वर्ष (पिछले वर्ष के वेतन पर) 20% बढ़ता है। B, A से ₹10,000 अधिक से शुरू करता है और हर वर्ष ₹6,000 की निश्चित वृद्धि पाता है। दो वर्ष बाद दोनों के वेतन बराबर हो जाते हैं। A का प्रारंभिक वेतन कितना था?","optionsHi":["₹50,000","₹55,000","₹45,000","₹60,000"],"explanationHi":"2 वर्ष बाद A के पास 1.44A और B के पास A + 10,000 + 12,000 है। अतः 0.44A = 22,000 और A = ₹50,000।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-92","question":"Mohan's income rises by 20% and his expenditure by 30%, yet his savings rise by 10%. What percentage of his income did he save originally?","options":["40%","60%","45%","50%"],"answer":3,"explanation":"Take income 100 and savings s: 120 − 1.3(100 − s) = 1.1s gives 0.2s = 10, so s = 50%. Alligation check: the 20% rise in income lies midway between 10% and 30%, so savings and spending are equal.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"मोहन की आय 20% और व्यय 30% बढ़ता है, फिर भी उसकी बचत 10% बढ़ती है। उसने मूल रूप से अपनी आय का कितना प्रतिशत बचाया था?","optionsHi":["40%","60%","45%","50%"],"explanationHi":"आय 100 और बचत s लें: 120 − 1.3(100 − s) = 1.1s से 0.2s = 10, अतः s = 50%। एलीगेशन से जाँच: आय की 20% वृद्धि 10% और 30% के ठीक बीच में है, इसलिए बचत और व्यय बराबर हैं।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-93","question":"A power board charges ₹5 per unit for the first 100 units, ₹7 per unit for the next 100 units and ₹10 per unit beyond 200 units, plus a 5% surcharge on the whole amount. If a bill is ₹2,100, how many units were consumed?","options":["300","260","290","280"],"answer":3,"explanation":"Before surcharge: 2,100 ÷ 1.05 = ₹2,000. The first 200 units cost 500 + 700 = ₹1,200, leaving ₹800 = 80 units at ₹10. Total 280 units.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"एक बिजली बोर्ड पहली 100 इकाइयों पर ₹5 प्रति इकाई, अगली 100 इकाइयों पर ₹7 प्रति इकाई और 200 इकाइयों से अधिक पर ₹10 प्रति इकाई लेता है, साथ ही पूरी राशि पर 5% अधिभार लगाता है। यदि बिल ₹2,100 है, तो कितनी इकाइयाँ खर्च हुईं?","optionsHi":["300","260","290","280"],"explanationHi":"अधिभार से पहले: 2,100 ÷ 1.05 = ₹2,000। पहली 200 इकाइयों का मूल्य 500 + 700 = ₹1,200 है, शेष ₹800 = ₹10 की दर से 80 इकाइयाँ। कुल 280 इकाइयाँ।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-94","question":"What is 40% of 3/5 of 750?","options":["300","225","180","450"],"answer":2,"explanation":"3/5 of 750 = 450, and 40% of 450 = 180. Or directly 0.4 × 0.6 = 0.24, and 0.24 × 750 = 180.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"750 के 3/5 का 40% कितना होता है?","optionsHi":["300","225","180","450"],"explanationHi":"750 का 3/5 = 450, और 450 का 40% = 180। या सीधे 0.4 × 0.6 = 0.24, और 0.24 × 750 = 180।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-95","question":"The ratio of A to B is 3 : 5. By what percent is A less than B?","options":["66.67%","40%","60%","25%"],"answer":1,"explanation":"A is 2 less than B on a base of 5: 2/5 × 100 = 40%. 66.67% is B's excess over A.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"A और B का अनुपात 3 : 5 है। A, B से कितने प्रतिशत कम है?","optionsHi":["66.67%","40%","60%","25%"],"explanationHi":"A, B से 2 कम है और आधार 5 है: 2/5 × 100 = 40%। 66.67% तो A के मुकाबले B की अधिकता है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-96","question":"When a number is decreased by 25% and 40 is then added, the result equals the number increased by 15%. What is the number?","options":["100","80","120","160"],"answer":0,"explanation":"0.75x + 40 = 1.15x, so 0.4x = 40 and x = 100. 160 equates the result with the original number, ignoring the 15% rise, and 80 uses a 25% rise instead of 15%.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"जब किसी संख्या में 25% की कमी की जाती है और फिर 40 जोड़ा जाता है, तो परिणाम उस संख्या में 15% की वृद्धि के बराबर होता है। संख्या क्या है?","optionsHi":["100","80","120","160"],"explanationHi":"0.75x + 40 = 1.15x, अतः 0.4x = 40 और x = 100। 160 में परिणाम को मूल संख्या के बराबर रखा गया है और 15% की वृद्धि अनदेखी की गई है, और 80 में 15% के बजाय 25% की वृद्धि ली गई है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-97","question":"In a district, 1,000 students appeared in the board exam in 2025 and 1,200 in 2026. The pass percentages were 75% and 80% respectively. What was the overall pass percentage for the two years together?","options":["77.5%","78%","76.36%","77.73%"],"answer":3,"explanation":"Passes = 750 + 960 = 1,710 out of 2,200 = 77.73%. The simple average 77.5% ignores that 2026 had more students.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk","questionHi":"एक जिले में 2025 में 1,000 विद्यार्थी और 2026 में 1,200 विद्यार्थी बोर्ड परीक्षा में बैठे। उत्तीर्ण प्रतिशत क्रमशः 75% और 80% थे। दोनों वर्षों को मिलाकर कुल उत्तीर्ण प्रतिशत क्या था?","optionsHi":["77.5%","78%","76.36%","77.73%"],"explanationHi":"उत्तीर्ण = 750 + 960 = 2,200 में से 1,710 = 77.73%। साधारण औसत 77.5% इस बात को अनदेखा करता है कि 2026 में विद्यार्थी अधिक थे।","subtopic":"marks-exams"},
  {"id":"quant-percentage-98","question":"The difference between 78% and 57% of a number is 3,276. What is 65% of the number?","options":["15,600","9,828","10,920","10,140"],"answer":3,"explanation":"21% of the number = 3,276, so 1% = 156 and 65% = 65 × 156 = 10,140.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk","questionHi":"किसी संख्या के 78% और 57% का अंतर 3,276 है। उसी संख्या का 65% कितना है?","optionsHi":["15,600","9,828","10,920","10,140"],"explanationHi":"संख्या का 21% = 3,276, अतः 1% = 156 और 65% = 65 × 156 = 10,140।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-99","question":"In a term exam, Ravi's marks in Maths are 20% more than in Science, and his English marks are 10% less than his Maths marks. If his total in the three subjects is 246, what did he score in English?","options":["90","75","81","84"],"answer":2,"explanation":"With Science = 100: Maths = 120, English = 108, total 328. One unit = 246/328 = 0.75, so English = 108 × 0.75 = 81.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक सत्र परीक्षा में रवि के गणित में अंक विज्ञान से 20% अधिक हैं, और अंग्रेज़ी में उसके अंक गणित के अंकों से 10% कम हैं। यदि तीनों विषयों में उसके कुल अंक 246 हैं, तो अंग्रेज़ी में उसने कितने अंक पाए?","optionsHi":["90","75","81","84"],"explanationHi":"विज्ञान = 100 लें: गणित = 120, अंग्रेज़ी = 108, कुल 328। एक इकाई = 246/328 = 0.75, अतः अंग्रेज़ी = 108 × 0.75 = 81।","subtopic":"marks-exams"},
  {"id":"quant-percentage-100","question":"If 20% of (A + B) equals 30% of (A − B), A is what percent of B?","options":["250%","500%","150%","400%"],"answer":1,"explanation":"0.2A + 0.2B = 0.3A − 0.3B gives 0.1A = 0.5B, so A = 5B, i.e. 500% of B.","difficulty":"hard","source":"SSC CGL · SSC CPO","questionHi":"यदि (A + B) का 20%, (A − B) के 30% के बराबर है, तो A, B का कितना प्रतिशत है?","optionsHi":["250%","500%","150%","400%"],"explanationHi":"0.2A + 0.2B = 0.3A − 0.3B से 0.1A = 0.5B, अतः A = 5B, अर्थात् B का 500%।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-101","question":"A vendor at a railway station sells 40% of his water bottles in the morning, 25% of the remaining in the afternoon and 30% of what is left in the evening. If 63 bottles remain, how many did he start with?","options":["200","180","210","250"],"answer":0,"explanation":"Fraction left = 0.6 × 0.75 × 0.7 = 0.315. Start = 63 ÷ 0.315 = 200. Adding 40 + 25 + 30 = 95% sold is the trap.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"एक रेलवे स्टेशन पर एक विक्रेता सुबह अपनी पानी की 40% बोतलें बेचता है, दोपहर में शेष का 25% और शाम को बचे हुए का 30% बेचता है। यदि 63 बोतलें बच जाती हैं, तो उसके पास शुरू में कितनी बोतलें थीं?","optionsHi":["200","180","210","250"],"explanationHi":"बचा हुआ अंश = 0.6 × 0.75 × 0.7 = 0.315। शुरू = 63 ÷ 0.315 = 200। 40 + 25 + 30 = 95% बिकी मान लेना जाल है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-102","question":"A student's aggregate in 5 papers of 100 marks each was 72%. Later he got 10 grace marks in each of two papers, and his marks in another paper, entered as 58, were corrected to 85. What is his corrected percentage?","options":["81.4%","76%","78.6%","80.2%"],"answer":0,"explanation":"Total was 360. Add 20 grace marks and 85 − 58 = 27 for the correction: 407/500 = 81.4%.","difficulty":"hard","source":"SSC CHSL · RRB NTPC","questionHi":"एक विद्यार्थी के 100-100 अंकों के 5 प्रश्नपत्रों में कुल अंक 72% थे। बाद में उसे दो प्रश्नपत्रों में से प्रत्येक में 10 कृपांक मिले, और एक अन्य प्रश्नपत्र में 58 दर्ज अंक सुधारकर 85 कर दिए गए। उसका सुधारा हुआ प्रतिशत क्या है?","optionsHi":["81.4%","76%","78.6%","80.2%"],"explanationHi":"कुल अंक 360 थे। 20 कृपांक और सुधार के 85 − 58 = 27 जोड़ें: 407/500 = 81.4%।","subtopic":"marks-exams"},
  {"id":"quant-percentage-103","question":"12.5% of A is equal to 20% of B, and B is ₹4,800 less than A. What is A + B?","options":["₹12,800","₹19,200","₹16,000","₹20,800"],"answer":3,"explanation":"A/B = 20/12.5 = 8/5. The difference is 3 parts = 4,800, so 1 part = 1,600 and A + B = 13 parts = ₹20,800.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"A का 12.5%, B के 20% के बराबर है, और B, A से ₹4,800 कम है। A + B कितना है?","optionsHi":["₹12,800","₹19,200","₹16,000","₹20,800"],"explanationHi":"A/B = 20/12.5 = 8/5। अंतर 3 भाग = 4,800, अतः 1 भाग = 1,600 और A + B = 13 भाग = ₹20,800।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-104","question":"In a college library, 35% of the books are in Hindi, 45% in English and the rest in regional languages. 20% of the Hindi, 30% of the English and 50% of the regional books are reference books. If there are 1,830 reference books, how many books does the library have?","options":["6,100","5,500","6,000","6,500"],"answer":2,"explanation":"Reference share = 0.35 × 20 + 0.45 × 30 + 0.20 × 50 = 7 + 13.5 + 10 = 30.5%. Total = 1,830 ÷ 0.305 = 6,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"एक कॉलेज पुस्तकालय में 35% पुस्तकें हिंदी में, 45% अंग्रेज़ी में और शेष क्षेत्रीय भाषाओं में हैं। हिंदी की 20%, अंग्रेज़ी की 30% और क्षेत्रीय भाषाओं की 50% पुस्तकें संदर्भ पुस्तकें हैं। यदि 1,830 संदर्भ पुस्तकें हैं, तो पुस्तकालय में कुल कितनी पुस्तकें हैं?","optionsHi":["6,100","5,500","6,000","6,500"],"explanationHi":"संदर्भ पुस्तकों का अंश = 0.35 × 20 + 0.45 × 30 + 0.20 × 50 = 7 + 13.5 + 10 = 30.5%। कुल = 1,830 ÷ 0.305 = 6,000।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-105","question":"The price of petrol goes up by 25%. By what percent must a car's mileage (km per litre) improve so that the fuel cost per km stays the same?","options":["20%","25%","12.5%","30%"],"answer":1,"explanation":"Cost per km = price ÷ mileage. To cancel a ×1.25 in price, mileage must also be ×1.25, i.e. improve by 25%. 20% is the cut needed in litres used, not the rise in mileage.","difficulty":"hard","source":"SSC CGL · CDS","questionHi":"पेट्रोल का मूल्य 25% बढ़ जाता है। एक कार की माइलेज (km प्रति लीटर) कितने प्रतिशत सुधरनी चाहिए ताकि प्रति km ईंधन की लागत वही रहे?","optionsHi":["20%","25%","12.5%","30%"],"explanationHi":"प्रति km लागत = मूल्य ÷ माइलेज। मूल्य के ×1.25 को निरस्त करने के लिए माइलेज भी ×1.25 होनी चाहिए, अर्थात् 25% सुधार। 20% प्रयुक्त लीटरों में आवश्यक कमी है, माइलेज में वृद्धि नहीं।","subtopic":"price-consumption"},
  {"id":"quant-percentage-106","question":"In a two-candidate election the loser got 35% of the valid votes and lost by 7,500 votes. If 1,500 votes were invalid, how many votes were cast?","options":["25,000","26,500","23,500","28,000"],"answer":1,"explanation":"Margin = 65% − 35% = 30% of valid votes = 7,500, so valid votes = 25,000. Votes cast = 25,000 + 1,500 = 26,500.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"दो उम्मीदवारों के चुनाव में हारने वाले को वैध मतों का 35% मिला और वह 7,500 मतों से हारा। यदि 1,500 मत अवैध थे, तो कुल कितने मत डाले गए?","optionsHi":["25,000","26,500","23,500","28,000"],"explanationHi":"अंतर = 65% − 35% = वैध मतों का 30% = 7,500, अतः वैध मत = 25,000। डाले गए मत = 25,000 + 1,500 = 26,500।","subtopic":"election-votes"},
  {"id":"quant-percentage-107","question":"The price of a commercial LPG cylinder rises by 15%. A dhaba cuts its gas use by 10%, but its monthly gas bill still rises by ₹1,050. What was its monthly gas bill earlier?","options":["₹30,000","₹21,000","₹35,000","₹20,000"],"answer":0,"explanation":"New bill = 1.15 × 0.9 = 1.035 of the old, a 3.5% rise. 3.5% = ₹1,050, so the old bill = ₹30,000. Taking the rise as 5% gives ₹21,000.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक व्यावसायिक LPG सिलेंडर का मूल्य 15% बढ़ जाता है। एक ढाबा अपनी गैस की खपत 10% घटा देता है, फिर भी उसका मासिक गैस बिल ₹1,050 बढ़ जाता है। उसका पहले का मासिक गैस बिल कितना था?","optionsHi":["₹30,000","₹21,000","₹35,000","₹20,000"],"explanationHi":"नया बिल = पुराने का 1.15 × 0.9 = 1.035, अर्थात् 3.5% की वृद्धि। 3.5% = ₹1,050, अतः पुराना बिल = ₹30,000। वृद्धि को 5% लेने पर ₹21,000 आता है।","subtopic":"price-consumption"},
  {"id":"quant-percentage-108","question":"A student was asked to find 8/5 of a number but found 5/8 of it instead. What is the percentage error in his answer?","options":["39%","62.5%","156%","60.9375%"],"answer":3,"explanation":"Error = (8/5 − 5/8) ÷ 8/5 = (64 − 25)/64 = 39/64 = 60.9375%. The error is always measured against the correct value.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक विद्यार्थी से किसी संख्या का 8/5 निकालने को कहा गया, लेकिन उसने उसका 5/8 निकाल लिया। उसके उत्तर में प्रतिशत त्रुटि कितनी है?","optionsHi":["39%","62.5%","156%","60.9375%"],"explanationHi":"त्रुटि = (8/5 − 5/8) ÷ 8/5 = (64 − 25)/64 = 39/64 = 60.9375%। त्रुटि हमेशा सही मान के आधार पर मापी जाती है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-109","question":"A cricket team won 60% of its first 30 matches in a season. How many of the remaining 20 matches must it win to finish the season with a 70% win record?","options":["18","14","17","20"],"answer":2,"explanation":"Wins so far = 18. For 70% of 50 matches it needs 35 wins, so 35 − 18 = 17 more.","difficulty":"hard","source":"SSC CHSL · RRB NTPC","questionHi":"एक क्रिकेट टीम ने एक सीज़न के अपने पहले 30 मैचों में से 60% जीते। सीज़न का अंत 70% जीत के रिकॉर्ड के साथ करने के लिए उसे शेष 20 मैचों में से कितने जीतने होंगे?","optionsHi":["18","14","17","20"],"explanationHi":"अब तक की जीत = 18। 50 मैचों के 70% के लिए उसे 35 जीत चाहिए, अतः 35 − 18 = 17 और जीतने होंगे।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-110","question":"A's marks are 25% of the total of B's and C's marks, and B's marks are 40% of the total of A's and C's marks. If C scored 360, what did A score?","options":["150","126","140","160"],"answer":2,"explanation":"A = 0.25B + 90 and B = 0.4A + 144. Substituting: A = 0.1A + 36 + 90, so 0.9A = 126 and A = 140 (B = 200; check 0.25 × 560 = 140).","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"A के अंक B और C के कुल अंकों के 25% हैं, और B के अंक A और C के कुल अंकों के 40% हैं। यदि C ने 360 अंक पाए, तो A ने कितने अंक पाए?","optionsHi":["150","126","140","160"],"explanationHi":"A = 0.25B + 90 और B = 0.4A + 144। प्रतिस्थापन से: A = 0.1A + 36 + 90, अतः 0.9A = 126 और A = 140 (B = 200; जाँच 0.25 × 560 = 140)।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-111","question":"A number is increased by 10%, the result is decreased by 10%, and that result is increased by 20%. The final value is 37.6 more than the original number. What is the number?","options":["188","200","240","160"],"answer":1,"explanation":"Multiplier = 1.1 × 0.9 × 1.2 = 1.188, an 18.8% rise. 18.8% = 37.6, so the number is 200.","difficulty":"hard","source":"SSC CHSL · SSC CGL","questionHi":"किसी संख्या में 10% की वृद्धि की जाती है, परिणाम में 10% की कमी की जाती है, और उस परिणाम में 20% की वृद्धि की जाती है। अंतिम मान मूल संख्या से 37.6 अधिक है। संख्या क्या है?","optionsHi":["188","200","240","160"],"explanationHi":"गुणक = 1.1 × 0.9 × 1.2 = 1.188, अर्थात् 18.8% की वृद्धि। 18.8% = 37.6, अतः संख्या 200 है।","subtopic":"successive-change"},
  {"id":"quant-percentage-112","question":"In a two-candidate election, if 10% of the winner's votes had gone to the loser instead, the loser would have won by 40 votes. If 1,840 valid votes were polled, by how many votes did the winner actually win?","options":["160","200","80","120"],"answer":0,"explanation":"L + 0.1W = 0.9W + 40, so L = 0.8W + 40. Then W + 0.8W + 40 = 1,840 gives W = 1,000 and L = 840. Actual margin = 160.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"दो उम्मीदवारों के चुनाव में, यदि विजेता के 10% मत हारने वाले को चले जाते, तो हारने वाला 40 मतों से जीत जाता। यदि कुल 1,840 वैध मत डाले गए, तो विजेता वास्तव में कितने मतों से जीता?","optionsHi":["160","200","80","120"],"explanationHi":"L + 0.1W = 0.9W + 40, अतः L = 0.8W + 40। फिर W + 0.8W + 40 = 1,840 से W = 1,000 और L = 840। वास्तविक अंतर = 160।","subtopic":"election-votes"},
  {"id":"quant-percentage-113","question":"A earns 25% more than B. A spends 80% of his income, while B saves 30% of his. If B saves ₹1,500 more than A, what is A's income?","options":["₹30,000","₹40,000","₹36,000","₹37,500"],"answer":3,"explanation":"A saves 20% of 1.25B = 0.25B; B saves 0.3B. So 0.05B = 1,500, B = ₹30,000 and A = 1.25 × 30,000 = ₹37,500.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"A, B से 25% अधिक कमाता है। A अपनी आय का 80% खर्च करता है, जबकि B अपनी आय का 30% बचाता है। यदि B, A से ₹1,500 अधिक बचाता है, तो A की आय कितनी है?","optionsHi":["₹30,000","₹40,000","₹36,000","₹37,500"],"explanationHi":"A, 1.25B का 20% = 0.25B बचाता है; B, 0.3B बचाता है। अतः 0.05B = 1,500, B = ₹30,000 और A = 1.25 × 30,000 = ₹37,500।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-114","question":"In a class, 60% of the students are boys. 25% of the boys and 40% of the girls scored above 90. Roughly what percentage of the students scoring above 90 are girls?","options":["40%","61.5%","48.4%","51.6%"],"answer":3,"explanation":"Per 100 students: boys above 90 = 15, girls = 16. Girls' share = 16/31 ≈ 51.6%. 40% is the girls' share of the class, not of the toppers.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"एक कक्षा में 60% विद्यार्थी लड़के हैं। 25% लड़कों और 40% लड़कियों ने 90 से ऊपर अंक पाए। 90 से ऊपर अंक पाने वाले विद्यार्थियों में लगभग कितने प्रतिशत लड़कियाँ हैं?","optionsHi":["40%","61.5%","48.4%","51.6%"],"explanationHi":"प्रति 100 विद्यार्थी: 90 से ऊपर लड़के = 15, लड़कियाँ = 16। लड़कियों का अंश = 16/31 ≈ 51.6%। 40% कक्षा में लड़कियों का अंश है, अव्वल आने वालों में नहीं।","subtopic":"marks-exams"},
  {"id":"quant-percentage-115","question":"A company's revenue grows by 20% and its costs grow by 10%. If profit was earlier 20% of revenue, by what percent does profit grow?","options":["10%","30%","60%","50%"],"answer":2,"explanation":"Take revenue 100 and cost 80, so profit 20. New profit = 120 − 88 = 32, a rise of 12 on 20 = 60%. Small changes in revenue and cost magnify profit change.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक कंपनी का राजस्व 20% और लागत 10% बढ़ती है। यदि पहले लाभ राजस्व का 20% था, तो लाभ कितने प्रतिशत बढ़ता है?","optionsHi":["10%","30%","60%","50%"],"explanationHi":"राजस्व 100 और लागत 80 लें, अतः लाभ 20। नया लाभ = 120 − 88 = 32, यानी 20 पर 12 की वृद्धि = 60%। राजस्व और लागत में छोटे परिवर्तन लाभ के परिवर्तन को बढ़ा देते हैं।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-116","question":"A man loses 20% of his money, then gains 20% on what is left, and then spends ₹40. He now has ₹440. How much did he start with?","options":["₹480","₹500","₹520","₹550"],"answer":1,"explanation":"Before spending he had ₹480 = 0.8 × 1.2 = 0.96 of the start. Start = 480 ÷ 0.96 = ₹500. A 20% loss followed by a 20% gain is a 4% net loss.","difficulty":"hard","source":"SSC CHSL · RRB NTPC","questionHi":"एक आदमी अपने पैसों का 20% खो देता है, फिर बचे हुए पर 20% कमाता है, और फिर ₹40 खर्च करता है। अब उसके पास ₹440 हैं। उसके पास शुरू में कितने थे?","optionsHi":["₹480","₹500","₹520","₹550"],"explanationHi":"खर्च से पहले उसके पास ₹480 = शुरुआत का 0.8 × 1.2 = 0.96 था। शुरुआत = 480 ÷ 0.96 = ₹500। 20% की हानि के बाद 20% का लाभ कुल मिलाकर 4% की हानि होती है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-117","question":"The pass mark in a test is 36%. Ravi scores 20% more than the pass mark and Sita scores 10% less than the pass mark. If Ravi scores 54 marks more than Sita, what are the maximum marks?","options":["500","450","540","600"],"answer":0,"explanation":"Ravi − Sita = 1.2P − 0.9P = 0.3P = 54, so the pass mark P = 180. Maximum = 180 ÷ 0.36 = 500.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक परीक्षा में उत्तीर्ण अंक 36% हैं। रवि उत्तीर्ण अंक से 20% अधिक और सीता उत्तीर्ण अंक से 10% कम अंक पाती है। यदि रवि के अंक सीता से 54 अधिक हैं, तो पूर्णांक कितना है?","optionsHi":["500","450","540","600"],"explanationHi":"रवि − सीता = 1.2P − 0.9P = 0.3P = 54, अतः उत्तीर्ण अंक P = 180। पूर्णांक = 180 ÷ 0.36 = 500।","subtopic":"marks-exams"},
  {"id":"quant-percentage-118","question":"The price of gold rises by 30% and a family cuts its gold purchase by 30%. What happens to its spending on gold?","options":["9% decrease","No change","9% increase","6% decrease"],"answer":0,"explanation":"Spending = price × quantity = 1.3 × 0.7 = 0.91, a 9% decrease. Equal opposite percentage changes always give a net loss of x²/100 %.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"सोने का मूल्य 30% बढ़ जाता है और एक परिवार अपनी सोने की खरीद 30% घटा देता है। सोने पर उसके व्यय का क्या होता है?","optionsHi":["9% की कमी","कोई परिवर्तन नहीं","9% की वृद्धि","6% की कमी"],"explanationHi":"व्यय = मूल्य × मात्रा = 1.3 × 0.7 = 0.91, अर्थात् 9% की कमी। बराबर प्रतिशत की विपरीत दिशा के परिवर्तनों से हमेशा x²/100 % की कुल हानि होती है।","subtopic":"price-consumption"},
  {"id":"quant-percentage-119","question":"₹15,000 is what percent of ₹2.5 lakh?","options":["0.6%","16.67%","60%","6%"],"answer":3,"explanation":"₹2.5 lakh = ₹2,50,000. 15,000/2,50,000 × 100 = 6%. Miscounting the zeros in a lakh gives 0.6% or 60%.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"₹15,000, ₹2.5 लाख का कितना प्रतिशत है?","optionsHi":["0.6%","16.67%","60%","6%"],"explanationHi":"₹2.5 लाख = ₹2,50,000। 15,000/2,50,000 × 100 = 6%। लाख में शून्य गिनने में गलती से 0.6% या 60% आता है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-120","question":"If 15% of x equals 20% of y, what is x : y?","options":["3 : 4","15 : 20","4 : 3","2 : 3"],"answer":2,"explanation":"0.15x = 0.2y gives x/y = 0.2/0.15 = 4/3. The quantity with the smaller percentage is the larger number.","difficulty":"easy","source":"SSC CHSL · SSC CGL","questionHi":"यदि x का 15%, y के 20% के बराबर है, तो x : y क्या है?","optionsHi":["3 : 4","15 : 20","4 : 3","2 : 3"],"explanationHi":"0.15x = 0.2y से x/y = 0.2/0.15 = 4/3। जिस राशि पर प्रतिशत कम होता है, वह संख्या बड़ी होती है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-121","question":"A number is increased by 30% and the result is then decreased by 30%. If the final value is 455, what was the number?","options":["455","500","520","650"],"answer":1,"explanation":"Multiplier = 1.3 × 0.7 = 0.91, so the number = 455 ÷ 0.91 = 500. Equal rise and fall always give a net fall of 30²/100 = 9%.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"किसी संख्या में 30% की वृद्धि की जाती है और फिर परिणाम में 30% की कमी की जाती है। यदि अंतिम मान 455 है, तो संख्या क्या थी?","optionsHi":["455","500","520","650"],"explanationHi":"गुणक = 1.3 × 0.7 = 0.91, अतः संख्या = 455 ÷ 0.91 = 500। बराबर वृद्धि और कमी से हमेशा 30²/100 = 9% की कुल कमी होती है।","subtopic":"successive-change"},
  {"id":"quant-percentage-122","question":"A firm has 900 employees, 30% of whom are women. If no one leaves, how many women must it hire so that women make up 40% of the staff?","options":["150","90","120","135"],"answer":0,"explanation":"(270 + w)/(900 + w) = 0.4 gives 270 + w = 360 + 0.4w, so 0.6w = 90 and w = 150. Hiring 90 ignores that the new hires also enlarge the total.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक फर्म में 900 कर्मचारी हैं, जिनमें से 30% महिलाएँ हैं। यदि कोई नहीं जाता, तो उसे कितनी महिलाओं को और नियुक्त करना होगा ताकि कर्मचारियों में महिलाएँ 40% हो जाएँ?","optionsHi":["150","90","120","135"],"explanationHi":"(270 + w)/(900 + w) = 0.4 से 270 + w = 360 + 0.4w, अतः 0.6w = 90 और w = 150। 90 की नियुक्ति इस बात को अनदेखा करती है कि नई नियुक्तियाँ कुल संख्या भी बढ़ा देती हैं।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-123","question":"If a% of b is 30 and b% of c is 45, then c is what percent more than a?","options":["50%","15%","33.33%","150%"],"answer":0,"explanation":"ab = 3,000 and bc = 4,500, so c/a = 1.5. Hence c is 50% more than a.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"यदि b का a% = 30 और c का b% = 45, तो c, a से कितने प्रतिशत अधिक है?","optionsHi":["50%","15%","33.33%","150%"],"explanationHi":"ab = 3,000 और bc = 4,500, अतः c/a = 1.5। इसलिए c, a से 50% अधिक है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-124","question":"Every week a reservoir loses 10% of its water to irrigation and then gains 5% of the remaining water from rain. After two such weeks it holds 89,302.5 kilolitres. How much did it hold at the start?","options":["95,000 kl","1,05,000 kl","98,000 kl","1,00,000 kl"],"answer":3,"explanation":"Weekly multiplier = 0.9 × 1.05 = 0.945. Start = 89,302.5 ÷ 0.945² = 89,302.5 ÷ 0.893025 = 1,00,000 kl.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"हर सप्ताह एक जलाशय सिंचाई में अपने पानी का 10% खो देता है और फिर बचे हुए पानी का 5% वर्षा से पा लेता है। ऐसे दो सप्ताह के बाद उसमें 89,302.5 किलोलीटर पानी है। शुरू में उसमें कितना पानी था?","optionsHi":["95,000 kl","1,05,000 kl","98,000 kl","1,00,000 kl"],"explanationHi":"साप्ताहिक गुणक = 0.9 × 1.05 = 0.945। शुरुआत = 89,302.5 ÷ 0.945² = 89,302.5 ÷ 0.893025 = 1,00,000 kl।","subtopic":"population-depreciation"},
  {"id":"quant-percentage-125","question":"A 3 kg batch of laddoo mix is 40% sugar. How much sugar must be added to make the mix 50% sugar?","options":["0.3 kg","0.5 kg","0.6 kg","0.75 kg"],"answer":2,"explanation":"Sugar = 1.2 kg, other = 1.8 kg, which stays fixed. At 50% sugar the other part is also 50%, so the total = 3.6 kg and sugar to add = 0.6 kg.","difficulty":"moderate","source":"SSC CHSL · RRB Group D","questionHi":"लड्डू के मिश्रण के 3 kg के एक बैच में 40% चीनी है। मिश्रण में 50% चीनी करने के लिए कितनी चीनी और मिलानी होगी?","optionsHi":["0.3 kg","0.5 kg","0.6 kg","0.75 kg"],"explanationHi":"चीनी = 1.2 kg, अन्य = 1.8 kg, जो स्थिर रहता है। 50% चीनी पर अन्य भाग भी 50% होता है, अतः कुल = 3.6 kg और मिलानी वाली चीनी = 0.6 kg।","subtopic":"mixtures-concentration"},
  {"id":"quant-percentage-126","question":"Scheme A pays a salesperson 5% commission on all sales. Scheme B pays ₹2,000 fixed plus 3% commission on sales above ₹10,000. For a certain month's sales, Scheme B pays ₹800 more than Scheme A. What were the sales?","options":["₹40,000","₹45,000","₹50,000","₹35,000"],"answer":1,"explanation":"B − A = 2,000 + 0.03(S − 10,000) − 0.05S = 1,700 − 0.02S = 800, so S = ₹45,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"योजना A एक विक्रेता को सभी बिक्री पर 5% कमीशन देती है। योजना B ₹2,000 निश्चित राशि और ₹10,000 से ऊपर की बिक्री पर 3% कमीशन देती है। किसी महीने की बिक्री पर योजना B, योजना A से ₹800 अधिक देती है। बिक्री कितनी थी?","optionsHi":["₹40,000","₹45,000","₹50,000","₹35,000"],"explanationHi":"B − A = 2,000 + 0.03(S − 10,000) − 0.05S = 1,700 − 0.02S = 800, अतः S = ₹45,000।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-127","question":"In a city, 52% of the people are men. 60% of the men and 45% of the women are literate. If there are 13,200 illiterate women, what is the population of the city?","options":["44,000","50,000","55,000","48,000"],"answer":1,"explanation":"Illiterate women = 48% × 55% = 26.4% of the population. Population = 13,200 ÷ 0.264 = 50,000.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk","questionHi":"एक शहर में 52% लोग पुरुष हैं। 60% पुरुष और 45% महिलाएँ साक्षर हैं। यदि 13,200 महिलाएँ निरक्षर हैं, तो शहर की जनसंख्या कितनी है?","optionsHi":["44,000","50,000","55,000","48,000"],"explanationHi":"निरक्षर महिलाएँ = जनसंख्या का 48% × 55% = 26.4%। जनसंख्या = 13,200 ÷ 0.264 = 50,000।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-128","question":"To pass, a candidate needs at least 40% in each of two papers (maximum 150 and 100 marks) and at least 50% in aggregate. If he scores 95 in the first paper, what is the minimum he needs in the second paper?","options":["40","30","50","45"],"answer":0,"explanation":"The aggregate rule needs only 125 − 95 = 30, but the paper-wise rule needs 40% of 100 = 40. Both must hold, so the minimum is 40.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"उत्तीर्ण होने के लिए एक परीक्षार्थी को दो प्रश्नपत्रों (पूर्णांक 150 और 100) में से प्रत्येक में कम से कम 40% और कुल मिलाकर कम से कम 50% अंक चाहिए। यदि वह पहले प्रश्नपत्र में 95 अंक पाता है, तो दूसरे प्रश्नपत्र में उसे न्यूनतम कितने अंक चाहिए?","optionsHi":["40","30","50","45"],"explanationHi":"कुल योग वाले नियम के लिए केवल 125 − 95 = 30 चाहिए, लेकिन प्रश्नपत्र-वार नियम के लिए 100 का 40% = 40 चाहिए। दोनों शर्तें पूरी होनी चाहिए, अतः न्यूनतम 40 है।","subtopic":"marks-exams"},
  {"id":"quant-percentage-129","question":"A water purifier removes 85% of the impurities present in each pass. After two passes the water has 45 ppm of impurities. What was the impurity level originally?","options":["300 ppm","1,800 ppm","2,250 ppm","2,000 ppm"],"answer":3,"explanation":"Each pass leaves 15%, so two passes leave 0.15² = 0.0225. Original = 45 ÷ 0.0225 = 2,000 ppm. Removing 170% in total is impossible, so 'subtract twice' is wrong.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एक जल शोधक प्रत्येक बार में मौजूद अशुद्धियों का 85% हटा देता है। दो बार के बाद पानी में 45 ppm अशुद्धियाँ हैं। मूल अशुद्धि स्तर क्या था?","optionsHi":["300 ppm","1,800 ppm","2,250 ppm","2,000 ppm"],"explanationHi":"प्रत्येक बार में 15% बचता है, अतः दो बार में 0.15² = 0.0225 बचता है। मूल = 45 ÷ 0.0225 = 2,000 ppm। कुल 170% हटाना असंभव है, इसलिए 'दो बार घटाना' गलत है।","subtopic":"population-depreciation"},
  {"id":"quant-percentage-130","question":"A coaching institute raises its fee by 20% and its enrolment falls by 15%. Its fee collection goes up by ₹36,000. What was the collection before the change?","options":["₹7,20,000","₹12,00,000","₹18,00,000","₹3,60,000"],"answer":2,"explanation":"New collection = 1.2 × 0.85 = 1.02 of the old, a 2% rise. 2% = ₹36,000, so the old collection = ₹18,00,000. Taking net change as 20 − 15 = 5% gives ₹7,20,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"एक कोचिंग संस्थान अपनी फीस 20% बढ़ाता है और उसके नामांकन में 15% की कमी आती है। उसका फीस संग्रह ₹36,000 बढ़ जाता है। परिवर्तन से पहले संग्रह कितना था?","optionsHi":["₹7,20,000","₹12,00,000","₹18,00,000","₹3,60,000"],"explanationHi":"नया संग्रह = पुराने का 1.2 × 0.85 = 1.02, अर्थात् 2% की वृद्धि। 2% = ₹36,000, अतः पुराना संग्रह = ₹18,00,000। कुल परिवर्तन 20 − 15 = 5% लेने पर ₹7,20,000 आता है।","subtopic":"price-consumption"},
  {"id":"quant-percentage-131","question":"A man's salary is cut by 20%. By what percent must the reduced salary be raised so that he gets 10% more than his original salary?","options":["30%","25%","37.5%","32.5%"],"answer":2,"explanation":"Take 100 → 80. He needs 110, a rise of 30 on 80 = 37.5%. Adding 20 + 10 = 30% uses the wrong base.","difficulty":"hard","source":"SSC CHSL · SSC CGL","questionHi":"एक व्यक्ति के वेतन में 20% की कटौती की जाती है। घटे हुए वेतन को कितने प्रतिशत बढ़ाया जाए ताकि उसे मूल वेतन से 10% अधिक मिले?","optionsHi":["30%","25%","37.5%","32.5%"],"explanationHi":"100 → 80 लें। उसे 110 चाहिए, यानी 80 पर 30 की वृद्धि = 37.5%। 20 + 10 = 30% जोड़ना गलत आधार लेना है।","subtopic":"successive-change"},
  {"id":"quant-percentage-132","question":"A 20-litre solution contains 25% acid. x litres of it are drawn off and replaced with pure acid, after which the solution is 40% acid. What is x?","options":["3","4","5","6"],"answer":1,"explanation":"Replacing x litres raises acid by x − 0.25x = 0.75x. Needed rise = (40 − 25)% of 20 = 3 L, so x = 3 ÷ 0.75 = 4.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"20 लीटर के एक घोल में 25% अम्ल है। इसमें से x लीटर निकालकर उसकी जगह शुद्ध अम्ल डाल दिया जाता है, जिसके बाद घोल में 40% अम्ल हो जाता है। x क्या है?","optionsHi":["3","4","5","6"],"explanationHi":"x लीटर बदलने पर अम्ल x − 0.25x = 0.75x बढ़ता है। आवश्यक वृद्धि = 20 का (40 − 25)% = 3 L, अतः x = 3 ÷ 0.75 = 4।","subtopic":"mixtures-concentration"},
  {"id":"quant-percentage-133","question":"A publisher cuts the price of a book by 25% and its sales rise by 40%. What happens to the revenue from the book?","options":["5% increase","15% increase","5% decrease","No change"],"answer":0,"explanation":"Revenue = price × sales = 0.75 × 1.4 = 1.05, a 5% increase. 40 − 25 = 15% ignores the product term (−10%).","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"एक प्रकाशक किसी पुस्तक का मूल्य 25% घटा देता है और उसकी बिक्री 40% बढ़ जाती है। पुस्तक से होने वाली आय का क्या होता है?","optionsHi":["5% की वृद्धि","15% की वृद्धि","5% की कमी","कोई परिवर्तन नहीं"],"explanationHi":"आय = मूल्य × बिक्री = 0.75 × 1.4 = 1.05, अर्थात् 5% की वृद्धि। 40 − 25 = 15% में गुणनफल पद (−10%) को अनदेखा कर दिया गया है।","subtopic":"price-consumption"},
  {"id":"quant-percentage-134","question":"If x increases by 25% and y decreases by 20%, by what percent does x/y change?","options":["5% increase","45% increase","50% increase","56.25% increase"],"answer":3,"explanation":"x/y becomes 1.25/0.8 = 1.5625 times, a 56.25% increase. Dividing by 0.8 is a 25% boost, not 20%.","difficulty":"hard","source":"SSC CGL · CDS","questionHi":"यदि x में 25% की वृद्धि और y में 20% की कमी होती है, तो x/y में कितने प्रतिशत परिवर्तन होता है?","optionsHi":["5% की वृद्धि","45% की वृद्धि","50% की वृद्धि","56.25% की वृद्धि"],"explanationHi":"x/y, 1.25/0.8 = 1.5625 गुना हो जाता है, अर्थात् 56.25% की वृद्धि। 0.8 से भाग देना 20% नहीं, 25% की वृद्धि है।","subtopic":"successive-change"},
  {"id":"quant-percentage-135","question":"In the first of two years a town's population grew by 8%. In the second year 5% of its residents moved out, and 6,000 new residents arrived. The population is now 1,08,600. What was it two years ago?","options":["96,000","1,05,000","98,000","1,00,000"],"answer":3,"explanation":"P × 1.08 × 0.95 + 6,000 = 1,08,600, so 1.026P = 1,02,600 and P = 1,00,000.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"दो वर्षों में से पहले वर्ष में एक कस्बे की जनसंख्या 8% बढ़ी। दूसरे वर्ष में उसके 5% निवासी बाहर चले गए, और 6,000 नए निवासी आए। अब जनसंख्या 1,08,600 है। दो वर्ष पहले यह कितनी थी?","optionsHi":["96,000","1,05,000","98,000","1,00,000"],"explanationHi":"P × 1.08 × 0.95 + 6,000 = 1,08,600, अतः 1.026P = 1,02,600 और P = 1,00,000।","subtopic":"population-depreciation"},
  {"id":"quant-percentage-136","question":"Of three numbers, the first is 20% of the sum of the other two and the second is 30% of the sum of the other two. Roughly what percent of the sum of the first two is the third?","options":["50%","47%","151.6%","100%"],"answer":2,"explanation":"a = 0.2(S − a) gives a = S/6; b = 0.3(S − b) gives b = 3S/13. With S = 78: a = 13, b = 18, c = 47. So c/(a + b) = 47/31 ≈ 151.6%.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"तीन संख्याओं में, पहली संख्या शेष दो के योग का 20% है और दूसरी संख्या शेष दो के योग का 30% है। तीसरी संख्या, पहली दो के योग का लगभग कितना प्रतिशत है?","optionsHi":["50%","47%","151.6%","100%"],"explanationHi":"a = 0.2(S − a) से a = S/6; b = 0.3(S − b) से b = 3S/13। S = 78 लें: a = 13, b = 18, c = 47। अतः c/(a + b) = 47/31 ≈ 151.6%।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-137","question":"Income above ₹5 lakh is taxed at 20% (income up to ₹5 lakh is tax-free), and a 4% cess is charged on the tax. If a person's total tax including cess is ₹52,000, what is his income?","options":["₹7,60,000","₹7,50,000","₹7,10,000","₹2,50,000"],"answer":1,"explanation":"Tax before cess = 52,000 ÷ 1.04 = ₹50,000, which is 20% of ₹2,50,000 above the exemption. Income = 5 + 2.5 = ₹7.5 lakh.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"₹5 लाख से ऊपर की आय पर 20% कर लगता है (₹5 लाख तक की आय कर-मुक्त है), और कर पर 4% उपकर लगता है। यदि किसी व्यक्ति का उपकर सहित कुल कर ₹52,000 है, तो उसकी आय कितनी है?","optionsHi":["₹7,60,000","₹7,50,000","₹7,10,000","₹2,50,000"],"explanationHi":"उपकर से पहले का कर = 52,000 ÷ 1.04 = ₹50,000, जो छूट सीमा से ऊपर के ₹2,50,000 का 20% है। आय = 5 + 2.5 = ₹7.5 लाख।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-138","question":"A number is 20% of a second number and 25% of a third number. The second number is what percent of the third?","options":["125%","80%","105%","45%"],"answer":0,"explanation":"a = 0.2b = 0.25c, so b = 1.25c: the second number is 125% of the third. 80% inverts the relation (c as a percent of b), and 105% or 45% wrongly add or subtract the percentages.","difficulty":"hard","source":"SSC CHSL · SSC CGL","questionHi":"एक संख्या दूसरी संख्या का 20% और तीसरी संख्या का 25% है। दूसरी संख्या, तीसरी का कितना प्रतिशत है?","optionsHi":["125%","80%","105%","45%"],"explanationHi":"a = 0.2b = 0.25c, अतः b = 1.25c: दूसरी संख्या तीसरी का 125% है। 80% संबंध को उलट देता है (b के प्रतिशत के रूप में c), और 105% या 45% में प्रतिशतों को गलत ढंग से जोड़ा या घटाया गया है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-139","question":"A milkman has 40 litres of milk with 5% water. How much water must he add so that water makes up 24% of the mixture?","options":["10 litres","7.6 litres","8 litres","12 litres"],"answer":0,"explanation":"Pure milk = 38 L stays fixed and must be 76% of the new total: 38 ÷ 0.76 = 50 L. Water to add = 50 − 40 = 10 L.","difficulty":"hard","source":"SSC CHSL · RRB NTPC","questionHi":"एक दूधवाले के पास 40 लीटर दूध है जिसमें 5% पानी है। मिश्रण में पानी 24% करने के लिए उसे कितना पानी मिलाना होगा?","optionsHi":["10 लीटर","7.6 लीटर","8 लीटर","12 लीटर"],"explanationHi":"शुद्ध दूध = 38 L स्थिर रहता है और नए कुल का 76% होना चाहिए: 38 ÷ 0.76 = 50 L। मिलाया जाने वाला पानी = 50 − 40 = 10 L।","subtopic":"mixtures-concentration"},
  {"id":"quant-percentage-140","question":"A laptop costs ₹60,000. A buyer pays 25% down and the rest through a 'no-cost EMI', which carries a processing fee of 2% of the financed amount plus 18% GST on that fee. How much does he pay in all?","options":["₹60,900","₹61,080","₹61,200","₹61,062"],"answer":3,"explanation":"Financed = ₹45,000. Fee = 2% = ₹900, plus GST 18% of 900 = ₹162. Total = 60,000 + 900 + 162 = ₹61,062.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk","questionHi":"एक लैपटॉप की कीमत ₹60,000 है। एक खरीदार 25% अग्रिम भुगतान करता है और शेष राशि 'नो-कॉस्ट EMI' के माध्यम से देता है, जिस पर वित्तपोषित राशि का 2% प्रोसेसिंग शुल्क और उस शुल्क पर 18% GST लगता है। वह कुल कितना भुगतान करता है?","optionsHi":["₹60,900","₹61,080","₹61,200","₹61,062"],"explanationHi":"वित्तपोषित राशि = ₹45,000। शुल्क = 2% = ₹900, साथ में 900 का 18% GST = ₹162। कुल = 60,000 + 900 + 162 = ₹61,062।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-141","question":"A shop's footfall rises by 25%, but the share of visitors who buy falls from 12% to 10%. If the average bill rises by 8%, by what percent do sales change?","options":["21% increase","15% increase","12.5% increase","8% increase"],"answer":2,"explanation":"Sales = visitors × conversion × bill = 1.25 × (10/12) × 1.08 = 1.125. A fall from 12% to 10% is a 1/6 drop, not a 2% drop.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक दुकान में आने वाले ग्राहकों की संख्या 25% बढ़ जाती है, लेकिन खरीदारी करने वाले आगंतुकों का हिस्सा 12% से घटकर 10% रह जाता है। यदि औसत बिल 8% बढ़ जाता है, तो बिक्री में कितने प्रतिशत परिवर्तन होता है?","optionsHi":["21% की वृद्धि","15% की वृद्धि","12.5% की वृद्धि","8% की वृद्धि"],"explanationHi":"बिक्री = आगंतुक × परिवर्तन दर × बिल = 1.25 × (10/12) × 1.08 = 1.125। 12% से 10% की गिरावट 1/6 की कमी है, 2% की कमी नहीं।","subtopic":"price-consumption"},
  {"id":"quant-percentage-142","question":"A phone battery loses 15% of its current charge every hour. Starting fully charged, after how many complete hours does the charge first fall below 50%?","options":["4","5","3","6"],"answer":1,"explanation":"0.85² = 0.7225, 0.85⁴ ≈ 0.522 and 0.85⁵ ≈ 0.444. So it first drops below 50% after 5 hours, not 50/15 ≈ 3.3.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एक फोन की बैटरी हर घंटे अपने वर्तमान चार्ज का 15% खो देती है। पूरी चार्ज से शुरू करने पर, कितने पूरे घंटों के बाद चार्ज पहली बार 50% से नीचे जाएगा?","optionsHi":["4","5","3","6"],"explanationHi":"0.85² = 0.7225, 0.85⁴ ≈ 0.522 और 0.85⁵ ≈ 0.444। अतः यह पहली बार 5 घंटे बाद 50% से नीचे जाता है, 50/15 ≈ 3.3 नहीं।","subtopic":"population-depreciation"},
  {"id":"quant-percentage-143","question":"p is 150% of q, and r is 60% of (p + q). Then (r − q) is what percent of p?","options":["50%","33.33%","25%","66.67%"],"answer":1,"explanation":"Take q = 100: p = 150, r = 0.6 × 250 = 150. r − q = 50, which is 50/150 = 33.33% of p.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"p, q का 150% है, और r, (p + q) का 60% है। तब (r − q), p का कितना प्रतिशत है?","optionsHi":["50%","33.33%","25%","66.67%"],"explanationHi":"q = 100 लें: p = 150, r = 0.6 × 250 = 150। r − q = 50, जो p का 50/150 = 33.33% है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-144","question":"A earns 25% more than B, and B earns 20% less than C. How does A's income compare with C's?","options":["It is 5% more than C's","It is 5% less than C's","It is equal to C's","It is 45% more than C's"],"answer":2,"explanation":"A = 1.25B and B = 0.8C, so A = 1.25 × 0.8 C = C. Adding the percentages (+25 − 20 = +5) is the trap.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A, B से 25% अधिक कमाता है, और B, C से 20% कम कमाता है। A की आय की C की आय से तुलना कैसे होती है?","optionsHi":["यह C की आय से 5% अधिक है","यह C की आय से 5% कम है","यह C की आय के बराबर है","यह C की आय से 45% अधिक है"],"explanationHi":"A = 1.25B और B = 0.8C, अतः A = 1.25 × 0.8 C = C। प्रतिशतों को जोड़ना (+25 − 20 = +5) जाल है।","subtopic":"successive-change"},
  {"id":"quant-percentage-145","question":"The price of petrol rises by 20% and, a month later, by a further 10%. By what percentage must a motorist cut his petrol consumption to keep his petrol bill unchanged?","options":["23.08%","24.24%","32%","30%"],"answer":1,"explanation":"The price factor is 1.2 × 1.1 = 1.32, so consumption must fall to 1/1.32 of its old level: a cut of 0.32/1.32 = 24.24%. Adding the rises to 30% gives 23.08%, and 32% is the net price rise, not the cut.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"पेट्रोल का मूल्य 20% बढ़ता है और एक महीने बाद 10% और बढ़ता है। एक वाहन चालक को अपने पेट्रोल का बिल अपरिवर्तित रखने के लिए अपनी पेट्रोल खपत कितने प्रतिशत घटानी चाहिए?","optionsHi":["23.08%","24.24%","32%","30%"],"explanationHi":"मूल्य गुणक = 1.2 × 1.1 = 1.32, अतः खपत अपने पुराने स्तर के 1/1.32 तक गिरनी चाहिए: कमी = 0.32/1.32 = 24.24%। वृद्धियों को जोड़कर 30% लेने पर 23.08% आता है, और 32% मूल्य की कुल वृद्धि है, कटौती नहीं।","subtopic":"price-consumption"},
  {"id":"quant-percentage-146","question":"In an election between two candidates, 10% of the registered voters did not vote and 5% of the votes cast were invalid. The winner got 55% of the valid votes and won by 2,565 votes. How many voters were registered?","options":["28,500","25,650","27,000","30,000"],"answer":3,"explanation":"Valid votes = 0.9 × 0.95 V = 0.855V, and the margin is 10% of them: 0.0855V = 2,565, so V = 30,000. Ignoring the invalid votes gives 28,500; 25,650 is the number of valid votes.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"दो उम्मीदवारों के बीच एक चुनाव में पंजीकृत मतदाताओं में से 10% ने मतदान नहीं किया और डाले गए मतों में से 5% अवैध थे। विजेता को वैध मतों का 55% मिला और वह 2,565 मतों से जीता। कितने मतदाता पंजीकृत थे?","optionsHi":["28,500","25,650","27,000","30,000"],"explanationHi":"वैध मत = 0.9 × 0.95 V = 0.855V, और अंतर इनका 10% है: 0.0855V = 2,565, अतः V = 30,000। अवैध मतों को अनदेखा करने पर 28,500 आता है; 25,650 वैध मतों की संख्या है।","subtopic":"election-votes"},
  {"id":"quant-percentage-147","question":"A student who scores 30% of the maximum marks fails by 36 marks, while another who scores 42% gets 48 marks more than the pass mark. What is the pass mark?","options":["66","210","246","294"],"answer":2,"explanation":"0.30M + 36 = 0.42M − 48, so 0.12M = 84, M = 700 and the pass mark = 210 + 36 = 246. Taking 0.12M = 48 − 36 (a sign slip) gives M = 100 and 66; 210 is just 30% of 700.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"पूर्णांक का 30% अंक पाने वाला एक विद्यार्थी 36 अंकों से अनुत्तीर्ण हो जाता है, जबकि 42% अंक पाने वाला दूसरा विद्यार्थी उत्तीर्ण अंक से 48 अंक अधिक पाता है। उत्तीर्ण अंक क्या है?","optionsHi":["66","210","246","294"],"explanationHi":"0.30M + 36 = 0.42M − 48, अतः 0.12M = 84, M = 700 और उत्तीर्ण अंक = 210 + 36 = 246। 0.12M = 48 − 36 लेने (चिह्न की भूल) पर M = 100 और 66 आता है; 210 तो केवल 700 का 30% है।","subtopic":"marks-exams"},
  {"id":"quant-percentage-148","question":"The price of an article rises by 20% and then by a further 20%. By what percentage must the new price now be cut to bring it back to the original price?","options":["30 5/9%","33 1/3%","40%","44%"],"answer":0,"explanation":"Two 20% rises make the price 1.2 × 1.2 = 1.44 times, so the cut needed is 0.44/1.44 = 11/36 = 30 5/9%. 33 1/3% adds two cuts of 16 2/3%, 44% takes the rise on the original price as the base, and 40% just adds the two rises.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"किसी वस्तु का मूल्य 20% बढ़ता है और फिर 20% और बढ़ जाता है। मूल मूल्य पर वापस लाने के लिए अब नए मूल्य में कितने प्रतिशत की कटौती करनी होगी?","optionsHi":["30 5/9%","33 1/3%","40%","44%"],"explanationHi":"दो बार 20% वृद्धि से मूल्य 1.2 × 1.2 = 1.44 गुना हो जाता है, अतः आवश्यक कटौती = 0.44/1.44 = 11/36 = 30 5/9%। 33 1/3% में 16 2/3% की दो कटौतियाँ जोड़ दी गई हैं, 44% में मूल मूल्य को आधार माना गया है, और 40% में दोनों वृद्धियाँ सीधे जोड़ दी गई हैं।","subtopic":"successive-change"},
  {"id":"quant-percentage-149","question":"How many litres of pure alcohol must be added to 40 litres of a 15% alcohol solution to make it 32% alcohol?","options":["6.8 L","21.25 L","160 L","10 L"],"answer":3,"explanation":"6 + x = 0.32(40 + x) gives 0.68x = 6.8, so x = 10 L. Taking 32% of only the original 40 L (12.8 − 6) gives 6.8 L, which ignores that the added alcohol also enlarges the mixture.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"15% अल्कोहल वाले 40 लीटर घोल में कितने लीटर शुद्ध अल्कोहल मिलाया जाए कि उसमें 32% अल्कोहल हो जाए?","optionsHi":["6.8 L","21.25 L","160 L","10 L"],"explanationHi":"6 + x = 0.32(40 + x) से 0.68x = 6.8, अतः x = 10 L। केवल मूल 40 L का 32% (12.8 − 6) लेने पर 6.8 L आता है, जो इस बात को अनदेखा करता है कि मिलाया गया अल्कोहल मिश्रण को भी बढ़ा देता है।","subtopic":"mixtures-concentration"},
  {"id":"quant-percentage-150","question":"A man spends 80% of his income. His income rises by 15% and his expenditure by 12%. By what percentage do his savings increase?","options":["3%","15%","27%","12%"],"answer":2,"explanation":"Take income 100: savings 20. New income 115, new spending 89.6, new savings 25.4: up 27%. Subtracting 12 from 15 (3%) treats the two changes as if they had the same base.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक व्यक्ति अपनी आय का 80% खर्च करता है। उसकी आय 15% और व्यय 12% बढ़ता है। उसकी बचत कितने प्रतिशत बढ़ती है?","optionsHi":["3%","15%","27%","12%"],"explanationHi":"आय 100 लें: बचत 20। नई आय 115, नया व्यय 89.6, नई बचत 25.4: 27% की वृद्धि। 15 में से 12 घटाना (3%) दोनों परिवर्तनों को ऐसे मानता है जैसे उनका आधार एक ही हो।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-151","question":"In a town, 60% of the people read newspaper A, 50% read newspaper B and 20% read neither. What percentage read exactly one of the two papers?","options":["80%","50%","30%","70%"],"answer":1,"explanation":"At least one = 80%, so both = 60 + 50 − 80 = 30% and exactly one = 80 − 30 = 50%. 80% counts those reading at least one; 30% is those reading both.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक कस्बे में 60% लोग समाचार पत्र A पढ़ते हैं, 50% समाचार पत्र B पढ़ते हैं और 20% दोनों में से कोई नहीं पढ़ते। कितने प्रतिशत लोग दोनों में से केवल एक ही पत्र पढ़ते हैं?","optionsHi":["80%","50%","30%","70%"],"explanationHi":"कम से कम एक = 80%, अतः दोनों = 60 + 50 − 80 = 30% और केवल एक = 80 − 30 = 50%। 80% कम से कम एक पढ़ने वालों को गिनता है; 30% दोनों पढ़ने वाले हैं।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-152","question":"A 50 kg heap of cucumbers is 99% water. After drying in the sun it is 98% water. What does the heap weigh now?","options":["49 kg","25 kg","49.5 kg","40 kg"],"answer":1,"explanation":"The solid part, 0.5 kg, does not change and is now 2% of the heap, so the heap weighs 0.5/0.02 = 25 kg. Taking 1% off the total (49.5 kg) mixes up percentage points with percent.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"खीरों के 50 kg के एक ढेर में 99% पानी है। धूप में सुखाने के बाद उसमें 98% पानी रह जाता है। अब ढेर का भार कितना है?","optionsHi":["49 kg","25 kg","49.5 kg","40 kg"],"explanationHi":"ठोस भाग 0.5 kg नहीं बदलता और अब ढेर का 2% है, अतः ढेर का भार 0.5/0.02 = 25 kg है। कुल में से 1% घटाना (49.5 kg) प्रतिशत अंक और प्रतिशत को आपस में मिला देता है।","subtopic":"mixtures-concentration"},
  {"id":"quant-percentage-153","question":"A's salary is 40% more than B's, and C's salary is 30% less than A's. C's salary is what percentage of B's?","options":["110%","70%","102.04%","98%"],"answer":3,"explanation":"C = 0.7 × 1.4 B = 0.98B, i.e. 98% of B's. Adding the changes (+40 − 30) gives 110%; 102.04% is B as a percentage of C.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A का वेतन B के वेतन से 40% अधिक है, और C का वेतन A के वेतन से 30% कम है। C का वेतन B के वेतन का कितना प्रतिशत है?","optionsHi":["110%","70%","102.04%","98%"],"explanationHi":"C = 0.7 × 1.4 B = 0.98B, अर्थात् B का 98%। परिवर्तनों को जोड़ने (+40 − 30) पर 110% आता है; 102.04%, C के प्रतिशत के रूप में B है।","subtopic":"successive-change"},
  {"id":"quant-percentage-154","question":"A theatre raises its ticket price by 25% and attendance falls by 16%. Its fixed cost equals 40% of the original revenue. By what percentage does its profit change?","options":["+8.33%","+5%","+9%","+12.5%"],"answer":0,"explanation":"Revenue: 100 → 1.25 × 0.84 × 100 = 105. Profit: 60 → 65, a rise of 5/60 = 8.33%. +5% is only the revenue change; +9% adds the percentages.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"एक सिनेमाघर अपने टिकट का मूल्य 25% बढ़ाता है और दर्शकों की संख्या 16% घट जाती है। उसकी स्थिर लागत मूल राजस्व के 40% के बराबर है। उसके लाभ में कितने प्रतिशत परिवर्तन होता है?","optionsHi":["+8.33%","+5%","+9%","+12.5%"],"explanationHi":"राजस्व: 100 → 1.25 × 0.84 × 100 = 105। लाभ: 60 → 65, यानी 5/60 = 8.33% की वृद्धि। +5% केवल राजस्व का परिवर्तन है; +9% में प्रतिशतों को जोड़ दिया गया है।","subtopic":"price-consumption"},
  {"id":"quant-percentage-155","question":"A student multiplied a number by 3/5 instead of 5/3. What is the percentage error in his answer?","options":["36%","64%","177.78%","40%"],"answer":1,"explanation":"Error = (5/3 − 3/5)/(5/3) = (16/15)/(5/3) = 16/25 = 64%. 36% is the wrong answer as a share of the right one; 177.78% measures the error against the wrong answer.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक विद्यार्थी ने किसी संख्या को 5/3 के बजाय 3/5 से गुणा कर दिया। उसके उत्तर में प्रतिशत त्रुटि कितनी है?","optionsHi":["36%","64%","177.78%","40%"],"explanationHi":"त्रुटि = (5/3 − 3/5)/(5/3) = (16/15)/(5/3) = 16/25 = 64%। 36% गलत उत्तर को सही उत्तर के अंश के रूप में दर्शाता है; 177.78% त्रुटि को गलत उत्तर के आधार पर मापता है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-156","question":"In an exam, 65% of the students passed in Maths, 58% passed in Science and 12% failed in both. If 1,050 students passed in both, how many passed in exactly one subject?","options":["1,590","2,640","690","900"],"answer":0,"explanation":"Passed both = 65 + 58 − 88 = 35%, so there are 3,000 students. Exactly one = (1,950 − 1,050) + (1,740 − 1,050) = 1,590. 2,640 counts those who passed at least one.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक परीक्षा में 65% विद्यार्थी गणित में उत्तीर्ण हुए, 58% विज्ञान में उत्तीर्ण हुए और 12% दोनों में अनुत्तीर्ण रहे। यदि 1,050 विद्यार्थी दोनों में उत्तीर्ण हुए, तो कितने विद्यार्थी ठीक एक ही विषय में उत्तीर्ण हुए?","optionsHi":["1,590","2,640","690","900"],"explanationHi":"दोनों में उत्तीर्ण = 65 + 58 − 88 = 35%, अतः कुल 3,000 विद्यार्थी हैं। ठीक एक = (1,950 − 1,050) + (1,740 − 1,050) = 1,590। 2,640 कम से कम एक में उत्तीर्ण होने वालों को गिनता है।","subtopic":"marks-exams"},
  {"id":"quant-percentage-157","question":"In a town the male population grew by 10% and the female population by 15% in a year, so that the whole population grew by 12% to 7,280. How many females are there now?","options":["2,600","4,485","2,990","4,290"],"answer":2,"explanation":"0.10M + 0.15F = 0.12(M + F) gives M : F = 3 : 2. The old population was 6,500, so there were 2,600 females, now 2,990. Inverting the ratio gives 4,485; 2,600 is last year's figure.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक कस्बे में एक वर्ष में पुरुष जनसंख्या 10% और महिला जनसंख्या 15% बढ़ी, जिससे कुल जनसंख्या 12% बढ़कर 7,280 हो गई। अब कितनी महिलाएँ हैं?","optionsHi":["2,600","4,485","2,990","4,290"],"explanationHi":"0.10M + 0.15F = 0.12(M + F) से M : F = 3 : 2। पुरानी जनसंख्या 6,500 थी, अतः 2,600 महिलाएँ थीं, जो अब 2,990 हैं। अनुपात उलटने पर 4,485 आता है; 2,600 पिछले वर्ष का आँकड़ा है।","subtopic":"population-depreciation"},
  {"id":"quant-percentage-158","question":"If 20% of (a + b) equals 30% of (a − b), then b is what percentage of a?","options":["20%","500%","66.67%","150%"],"answer":0,"explanation":"0.2a + 0.2b = 0.3a − 0.3b gives 0.5b = 0.1a, so b = 20% of a. 500% is a as a percentage of b.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि (a + b) का 20%, (a − b) के 30% के बराबर है, तो b, a का कितना प्रतिशत है?","optionsHi":["20%","500%","66.67%","150%"],"explanationHi":"0.2a + 0.2b = 0.3a − 0.3b से 0.5b = 0.1a, अतः b = a का 20%। 500% तो b के प्रतिशत के रूप में a है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-159","question":"Petrol prices rise by 30%. A car owner drives 10% fewer kilometres and improves his car's mileage (km per litre) by 10%. By what percentage does his monthly fuel spending change?","options":["+10%","+5.3%","+17%","+6.36%"],"answer":3,"explanation":"Spending ∝ price × distance ÷ mileage = 1.3 × 0.9 ÷ 1.1 = 1.0636: up 6.36%. Multiplying by 0.9 for the mileage gain (instead of dividing by 1.1) gives +5.3%; +10% just adds the rates.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"पेट्रोल के मूल्य 30% बढ़ जाते हैं। एक कार मालिक 10% कम किलोमीटर चलाता है और अपनी कार की माइलेज (km प्रति लीटर) 10% सुधार लेता है। उसके मासिक ईंधन व्यय में कितने प्रतिशत परिवर्तन होता है?","optionsHi":["+10%","+5.3%","+17%","+6.36%"],"explanationHi":"व्यय ∝ मूल्य × दूरी ÷ माइलेज = 1.3 × 0.9 ÷ 1.1 = 1.0636: 6.36% की वृद्धि। माइलेज सुधार के लिए 1.1 से भाग देने के बजाय 0.9 से गुणा करने पर +5.3% आता है; +10% केवल दरों को जोड़ देता है।","subtopic":"price-consumption"},
  {"id":"quant-percentage-160","question":"Two numbers are 30% and 40% less than a third number. The first number is what percentage of the second?","options":["116.67%","85.71%","110%","90%"],"answer":0,"explanation":"First = 0.7T and second = 0.6T, so first/second = 7/6 = 116.67%. 85.71% is the second as a share of the first.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"दो संख्याएँ किसी तीसरी संख्या से क्रमशः 30% और 40% कम हैं। पहली संख्या दूसरी संख्या का कितना प्रतिशत है?","optionsHi":["116.67%","85.71%","110%","90%"],"explanationHi":"पहली = 0.7T और दूसरी = 0.6T, अतः पहली/दूसरी = 7/6 = 116.67%। 85.71% पहली के अंश के रूप में दूसरी है।","subtopic":"successive-change"},
  {"id":"quant-percentage-161","question":"In a village, 52% of the people are male. 75% of the males and 50% of the females are literate. What percentage of the literate people are female?","options":["48%","24%","61.9%","38.1%"],"answer":3,"explanation":"Literate: males 39% and females 24% of the village, 63% in all; females are 24/63 = 38.1% of the literate. 24% is females' share of the whole village.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक गाँव में 52% लोग पुरुष हैं। 75% पुरुष और 50% महिलाएँ साक्षर हैं। साक्षर लोगों में कितने प्रतिशत महिलाएँ हैं?","optionsHi":["48%","24%","61.9%","38.1%"],"explanationHi":"साक्षर: पुरुष गाँव का 39% और महिलाएँ 24% हैं, कुल 63%; साक्षर लोगों में महिलाएँ 24/63 = 38.1% हैं। 24% पूरे गाँव में महिलाओं का अंश है।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-162","question":"A jar full of honey weighs 1.8 kg. When 40% of the honey is used, the jar and the remaining honey weigh 1.32 kg. What percentage of the full weight is the empty jar?","options":["50%","26.67%","33.33%","66.67%"],"answer":2,"explanation":"The 0.48 kg used is 40% of the honey, so the honey weighs 1.2 kg and the jar 0.6 kg: 0.6/1.8 = 33.33%. 50% compares the jar with the honey, not with the full weight.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"शहद से भरे एक जार का भार 1.8 kg है। जब 40% शहद प्रयोग कर लिया जाता है, तो जार और बचे हुए शहद का भार 1.32 kg होता है। खाली जार का भार पूरे भार का कितना प्रतिशत है?","optionsHi":["50%","26.67%","33.33%","66.67%"],"explanationHi":"प्रयुक्त 0.48 kg शहद का 40% है, अतः शहद का भार 1.2 kg और जार का 0.6 kg है: 0.6/1.8 = 33.33%। 50% जार की तुलना शहद से करता है, पूरे भार से नहीं।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-163","question":"Consider: I. A 10% rise followed by a 10% fall leaves a price 1% lower than it began. II. If x is 25% more than y, then y is 25% less than x. III. Raising a rectangle's length by 20% and cutting its breadth by 20% reduces its area by 4%. Which are true?","options":["I only","I and III only","I, II and III","II and III only"],"answer":1,"explanation":"I: 1.1 × 0.9 = 0.99, true. III: 1.2 × 0.8 = 0.96, true. II is false: y = x/1.25 = 0.8x, so y is 20% less than x.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"विचार कीजिए: I. 10% की वृद्धि के बाद 10% की कमी होने पर मूल्य शुरुआत से 1% कम रह जाता है। II. यदि x, y से 25% अधिक है, तो y, x से 25% कम है। III. किसी आयत की लंबाई 20% बढ़ाने और चौड़ाई 20% घटाने से उसका क्षेत्रफल 4% कम हो जाता है। कौन-से सही हैं?","optionsHi":["केवल I","केवल I और III","I, II और III","केवल II और III"],"explanationHi":"I: 1.1 × 0.9 = 0.99, सही। III: 1.2 × 0.8 = 0.96, सही। II गलत है: y = x/1.25 = 0.8x, अतः y, x से 20% कम है।","subtopic":"successive-change"},
  {"id":"quant-percentage-164","question":"After 12% tax is deducted from a salary and then 5% of the remainder goes to a pension fund, the take-home pay is ₹41,800. What is the gross salary?","options":["₹50,361.45","₹50,000","₹48,906","₹47,500"],"answer":1,"explanation":"Take-home = 0.88 × 0.95 G = 0.836G, so G = ₹50,000. Deducting 17% at once gives ₹50,361.45; adding 17% to the take-home gives ₹48,906.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"किसी वेतन में से 12% कर काटने और फिर शेष का 5% पेंशन कोष में जाने के बाद, हाथ में आने वाला वेतन ₹41,800 है। सकल वेतन कितना है?","optionsHi":["₹50,361.45","₹50,000","₹48,906","₹47,500"],"explanationHi":"हाथ में आने वाला वेतन = 0.88 × 0.95 G = 0.836G, अतः G = ₹50,000। एक साथ 17% काटने पर ₹50,361.45 आता है; हाथ में आने वाले वेतन में 17% जोड़ने पर ₹48,906।","subtopic":"income-expenditure"},
  {"id":"quant-percentage-165","question":"A 20% fall in the price of rice lets a man buy 5 kg more for ₹1,200. What was the original price per kg?","options":["₹60","₹48","₹57.60","₹38.40"],"answer":0,"explanation":"He saves 20% of 1,200 = ₹240, which buys 5 kg at the new price: ₹48/kg. The old price is 48/0.8 = ₹60. ₹48 is the new price; 48 × 1.2 = ₹57.60 uses the wrong base.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"चावल के मूल्य में 20% की गिरावट से एक आदमी ₹1,200 में 5 kg अधिक खरीद पाता है। प्रति kg मूल कीमत क्या थी?","optionsHi":["₹60","₹48","₹57.60","₹38.40"],"explanationHi":"वह 1,200 का 20% = ₹240 बचाता है, जो नए मूल्य पर 5 kg खरीदता है: ₹48/kg। पुराना मूल्य 48/0.8 = ₹60 है। ₹48 नया मूल्य है; 48 × 1.2 = ₹57.60 में गलत आधार लिया गया है।","subtopic":"price-consumption"},
  {"id":"quant-percentage-166","question":"In a class, 40% of the students are girls. When 20 more boys join, boys make up 65% of the class. How many girls are there?","options":["56","84","160","76"],"answer":0,"explanation":"(0.6N + 20)/(N + 20) = 0.65 gives 0.05N = 7, so N = 140 and there are 56 girls. Forgetting that the class size also grows by 20 gives N = 400 and 160 girls.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक कक्षा में 40% विद्यार्थी लड़कियाँ हैं। जब 20 और लड़के शामिल होते हैं, तो कक्षा में लड़के 65% हो जाते हैं। कक्षा में कितनी लड़कियाँ हैं?","optionsHi":["56","84","160","76"],"explanationHi":"(0.6N + 20)/(N + 20) = 0.65 से 0.05N = 7, अतः N = 140 और 56 लड़कियाँ हैं। यह भुला देने पर कि कक्षा का आकार भी 20 बढ़ता है, N = 400 और 160 लड़कियाँ आती हैं।","subtopic":"basics-conversion"},
  {"id":"quant-percentage-167","question":"If 15% of A = 25% of B = 35% of C, what is A : B : C?","options":["15 : 25 : 35","7 : 5 : 3","35 : 21 : 15","3 : 5 : 7"],"answer":2,"explanation":"Equal products mean the numbers are inversely proportional to the percentages: 1/15 : 1/25 : 1/35. Multiplying by 525 gives 35 : 21 : 15.","difficulty":"very-hard","questionHi":"यदि A का 15% = B का 25% = C का 35%, तो A : B : C क्या है?","optionsHi":["15 : 25 : 35","7 : 5 : 3","35 : 21 : 15","3 : 5 : 7"],"explanationHi":"गुणनफल बराबर हैं, इसलिए संख्याएँ प्रतिशतों के व्युत्क्रमानुपाती हैं: 1/15 : 1/25 : 1/35। 525 से गुणा करने पर 35 : 21 : 15।","subtopic":"basics-conversion","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-168","question":"If 60% of (x − y) = 40% of (x + y), then y is what percentage of x?","options":["20%","25%","16.67%","80%"],"answer":0,"explanation":"0.6x − 0.6y = 0.4x + 0.4y gives 0.2x = y, so y is 20% of x. The 25% comes from comparing x with y instead of y with x.","difficulty":"hard","questionHi":"यदि (x − y) का 60% = (x + y) का 40%, तो y, x का कितना प्रतिशत है?","optionsHi":["20%","25%","16.67%","80%"],"explanationHi":"0.6x − 0.6y = 0.4x + 0.4y से 0.2x = y, अतः y, x का 20% है। 25% तब आता है जब y की तुलना x से करने के बजाय x की तुलना y से की जाती है।","subtopic":"basics-conversion","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-169","question":"x is 20% more than y, and z is 25% less than y. What percentage of z is x?","options":["145%","95%","62.5%","160%"],"answer":3,"explanation":"Take y = 100: x = 120 and z = 75, so x/z = 120/75 = 160%. Adding 20 + 25 gives the trap 145%.","difficulty":"moderate","questionHi":"x, y से 20% अधिक है और z, y से 25% कम है। x, z का कितना प्रतिशत है?","optionsHi":["145%","95%","62.5%","160%"],"explanationHi":"y = 100 लें: x = 120 और z = 75, अतः x/z = 120/75 = 160%। 20 + 25 जोड़ने पर भ्रामक उत्तर 145% आता है।","subtopic":"basics-conversion","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-170","question":"In a school 40% of the students are girls. If 25% of the boys and 40% of the girls take art, what percentage of all students take art?","options":["32.5%","31%","30%","28%"],"answer":1,"explanation":"Boys are 60% of the school: 60% × 25% = 15%. Girls are 40%: 40% × 40% = 16%. Total = 15% + 16% = 31%. The simple average of 25% and 40% is 32.5%, ignoring the different group sizes.","difficulty":"moderate","questionHi":"एक विद्यालय में 40% विद्यार्थी लड़कियाँ हैं। यदि 25% लड़के और 40% लड़कियाँ कला विषय लेते हैं, तो सभी विद्यार्थियों का कितना प्रतिशत कला विषय लेता है?","optionsHi":["32.5%","31%","30%","28%"],"explanationHi":"लड़के विद्यालय के 60% हैं: 60% × 25% = 15%। लड़कियाँ 40% हैं: 40% × 40% = 16%। कुल = 15% + 16% = 31%। 25% और 40% का साधारण औसत 32.5% है, जिसमें समूहों के अलग-अलग आकार की उपेक्षा है।","subtopic":"basics-conversion","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-171","question":"Consider: I. 20% of 50% of a number is 10% of the number. II. x% of y is always equal to y% of x. III. If A is 25% more than B, then B is 25% less than A. IV. A 50% increase followed by a 50% decrease restores the original value. How many of these statements are correct?","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. III is false because B is 20% less than A, and IV is false because 1.5 × 0.5 = 0.75, a 25% net fall.","difficulty":"hard","questionHi":"विचार कीजिए: I. किसी संख्या के 50% का 20%, उस संख्या का 10% होता है। II. y का x%, सदैव x का y% के बराबर होता है। III. यदि A, B से 25% अधिक है, तो B, A से 25% कम है। IV. 50% वृद्धि के बाद 50% कमी करने पर मूल मान वापस मिल जाता है। इनमें से कितने कथन सही हैं?","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। III गलत है क्योंकि B, A से 20% कम है, और IV गलत है क्योंकि 1.5 × 0.5 = 0.75, यानी कुल 25% की कमी।","subtopic":"basics-conversion","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-172","question":"The difference between 78% of a number and 59% of the same number is 323. What is 24% of the number?","options":["380","456","323","408"],"answer":3,"explanation":"78% − 59% = 19% of the number = 323, so the number is 1,700 and 24% of it is 408.","difficulty":"hard","questionHi":"किसी संख्या के 78% और उसी संख्या के 59% का अंतर 323 है। उस संख्या का 24% क्या है?","optionsHi":["380","456","323","408"],"explanationHi":"78% − 59% = संख्या का 19% = 323, अतः संख्या 1,700 है और उसका 24% = 408।","subtopic":"basics-conversion","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-173","question":"A price is raised by 20%, then reduced by x%, then raised by 25%, and the final price equals the original price. What is x?","options":["33.33%","20%","25%","30%"],"answer":0,"explanation":"1.2 × (1 − x/100) × 1.25 = 1 gives 1 − x/100 = 2/3, so x = 33.33%. The two rises together multiply the price by 1.5.","difficulty":"hard","questionHi":"किसी मूल्य को 20% बढ़ाया जाता है, फिर x% घटाया जाता है, फिर 25% बढ़ाया जाता है और अंतिम मूल्य मूल मूल्य के बराबर हो जाता है। x का मान क्या है?","optionsHi":["33.33%","20%","25%","30%"],"explanationHi":"1.2 × (1 − x/100) × 1.25 = 1 से 1 − x/100 = 2/3, अतः x = 33.33%। दोनों वृद्धियाँ मिलकर मूल्य को 1.5 गुना कर देती हैं।","subtopic":"successive-change","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-174","question":"A number is increased by 10%, decreased by 10%, increased by 10% and decreased by 10%, in that order. What is the net change?","options":["No change","2% decrease","1.99% decrease","0.99% decrease"],"answer":2,"explanation":"The factor is (1.1 × 0.9)² = 0.99² = 0.9801, a net decrease of 1.99%. A single rise-and-fall pair gives only 1%.","difficulty":"moderate","questionHi":"एक संख्या को क्रमशः 10% बढ़ाया, 10% घटाया, 10% बढ़ाया और 10% घटाया जाता है। कुल परिवर्तन क्या है?","optionsHi":["कोई परिवर्तन नहीं","2% की कमी","1.99% की कमी","0.99% की कमी"],"explanationHi":"गुणक (1.1 × 0.9)² = 0.99² = 0.9801 है, अर्थात् कुल 1.99% की कमी। केवल एक वृद्धि-कमी युग्म से सिर्फ 1% कमी आती है।","subtopic":"successive-change","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-175","question":"A's income is 25% more than B's and B's income is 20% more than C's. By what percentage is C's income less than A's?","options":["50%","30%","25%","33.33%"],"answer":3,"explanation":"With C = 100, B = 120 and A = 150. C is less than A by 50/150 = 33.33%. The 50% is the percentage by which A exceeds C.","difficulty":"hard","questionHi":"A की आय B की आय से 25% अधिक है और B की आय C की आय से 20% अधिक है। C की आय A की आय से कितने प्रतिशत कम है?","optionsHi":["50%","30%","25%","33.33%"],"explanationHi":"C = 100 लें, तो B = 120 और A = 150। C, A से 50/150 = 33.33% कम है। 50% वह प्रतिशत है जिससे A, C से अधिक है।","subtopic":"successive-change","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-176","question":"A number is increased by x% and the result is then decreased by x%. The final number is 96% of the original. What is x?","options":["4%","20%","16%","25%"],"answer":1,"explanation":"The net factor is (1 + x/100)(1 − x/100) = 1 − (x/100)². Setting it to 0.96 gives (x/100)² = 0.04, so x = 20%.","difficulty":"hard","questionHi":"एक संख्या को x% बढ़ाया जाता है और फिर परिणाम को x% घटाया जाता है। अंतिम संख्या मूल संख्या की 96% है। x का मान क्या है?","optionsHi":["4%","20%","16%","25%"],"explanationHi":"कुल गुणक (1 + x/100)(1 − x/100) = 1 − (x/100)² है। इसे 0.96 के बराबर रखने पर (x/100)² = 0.04, अतः x = 20%।","subtopic":"successive-change","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-177","question":"A shopkeeper raises the price of an article by 20% for the festival season and then offers a 20% discount on the new price. The article sells for ₹2,304. What was the price before the increase?","options":["₹2,880","₹1,920","₹2,400","₹2,500"],"answer":2,"explanation":"The net factor is 1.2 × 0.8 = 0.96, so the original price = 2,304/0.96 = ₹2,400. Dividing by 0.8 alone gives ₹2,880.","difficulty":"moderate","questionHi":"एक दुकानदार त्योहार के मौसम में एक वस्तु का मूल्य 20% बढ़ाता है और फिर नए मूल्य पर 20% छूट देता है। वस्तु ₹2,304 में बिकती है। मूल्य बढ़ाने से पहले क्या था?","optionsHi":["₹2,880","₹1,920","₹2,400","₹2,500"],"explanationHi":"कुल गुणक 1.2 × 0.8 = 0.96 है, अतः मूल मूल्य = 2,304/0.96 = ₹2,400। केवल 0.8 से भाग देने पर ₹2,880 आता है।","subtopic":"successive-change","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-178","question":"Assertion (A): If a quantity is increased by 25% and then decreased by 25%, it returns to its original value. Reason (R): The net multiplying factor is 1.25 × 0.75 = 0.9375.","options":["A is false but R is true","Both A and R are true and R explains A","A is true but R is false","Both A and R are false"],"answer":0,"explanation":"1.25 × 0.75 = 0.9375, so the quantity ends 6.25% below its original value. Hence A is false, while R states the correct factor.","difficulty":"moderate","questionHi":"अभिकथन (A): यदि किसी राशि को 25% बढ़ाकर फिर 25% घटाया जाए, तो वह अपने मूल मान पर लौट आती है। कारण (R): कुल गुणक 1.25 × 0.75 = 0.9375 है।","optionsHi":["A असत्य है परंतु R सत्य है","A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A सत्य है परंतु R असत्य है","A और R दोनों असत्य हैं"],"explanationHi":"1.25 × 0.75 = 0.9375, अतः राशि अपने मूल मान से 6.25% कम रह जाती है। इसलिए A असत्य है, जबकि R सही गुणक बताता है।","subtopic":"successive-change","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-179","question":"The population of a village is now 8,000. Last year it fell by 20%, and the year before that it rose by 25%. What was the population two years ago?","options":["8,000","10,000","12,500","6,400"],"answer":0,"explanation":"Work backwards: 8,000/0.8 = 10,000 a year ago, and 10,000/1.25 = 8,000 two years ago. The rise and fall cancel exactly, so 10,000 is only the intermediate value.","difficulty":"very-hard","questionHi":"एक गाँव की जनसंख्या अब 8,000 है। पिछले वर्ष उसमें 20% की कमी आई थी और उससे पहले वर्ष 25% की वृद्धि हुई थी। दो वर्ष पहले जनसंख्या कितनी थी?","optionsHi":["8,000","10,000","12,500","6,400"],"explanationHi":"पीछे की ओर चलें: 8,000/0.8 = 10,000 एक वर्ष पहले, और 10,000/1.25 = 8,000 दो वर्ष पहले। वृद्धि और कमी ठीक एक-दूसरे को काट देती हैं, अतः 10,000 केवल मध्यवर्ती मान है।","subtopic":"population-depreciation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-180","question":"In a town 55% of the people are men and 45% are women. The number of men increases by 20% and the number of women by 10%. What percentage of the new population is male?","options":["56%","58.5%","57.14%","60%"],"answer":2,"explanation":"Take 100 people: men 55 × 1.2 = 66, women 45 × 1.1 = 49.5, total 115.5. Male share = 66/115.5 = 57.14%.","difficulty":"very-hard","questionHi":"एक कस्बे में 55% लोग पुरुष और 45% महिलाएँ हैं। पुरुषों की संख्या 20% और महिलाओं की संख्या 10% बढ़ती है। नई जनसंख्या में पुरुषों का प्रतिशत क्या है?","optionsHi":["56%","58.5%","57.14%","60%"],"explanationHi":"100 लोग लें: पुरुष 55 × 1.2 = 66, महिलाएँ 45 × 1.1 = 49.5, कुल 115.5। पुरुषों का हिस्सा = 66/115.5 = 57.14%।","subtopic":"population-depreciation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-181","question":"In a village 40% of the people are literate. If 50% of the males and 30% of the females are literate, what is the ratio of males to females?","options":["2 : 3","1 : 1","3 : 2","3 : 5"],"answer":1,"explanation":"40 is exactly midway between 30 and 50, so by alligation the two groups are equal in size: males : females = 1 : 1.","difficulty":"very-hard","questionHi":"एक गाँव में 40% लोग साक्षर हैं। यदि 50% पुरुष और 30% महिलाएँ साक्षर हैं, तो पुरुषों और महिलाओं का अनुपात क्या है?","optionsHi":["2 : 3","1 : 1","3 : 2","3 : 5"],"explanationHi":"40, 30 और 50 के ठीक बीच में है, अतः मिश्रण-विधि से दोनों समूह बराबर हैं: पुरुष : महिलाएँ = 1 : 1।","subtopic":"population-depreciation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-182","question":"A machine bought for ₹80,000 depreciates by 10% in the first year, 15% in the second year and 20% in the third year, each on the value at the start of that year. What is its value after 3 years?","options":["₹44,000","₹49,130","₹52,000","₹48,960"],"answer":3,"explanation":"Value = 80,000 × 0.90 × 0.85 × 0.80 = ₹48,960. Adding the rates (45%) would give ₹44,000.","difficulty":"moderate","questionHi":"₹80,000 में खरीदी गई एक मशीन का मूल्य पहले वर्ष 10%, दूसरे वर्ष 15% और तीसरे वर्ष 20% घटता है, प्रत्येक उस वर्ष के आरंभिक मूल्य पर। 3 वर्ष बाद उसका मूल्य क्या है?","optionsHi":["₹44,000","₹49,130","₹52,000","₹48,960"],"explanationHi":"मूल्य = 80,000 × 0.90 × 0.85 × 0.80 = ₹48,960। दरों को जोड़ने (45%) पर ₹44,000 आता।","subtopic":"population-depreciation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-183","question":"A city's population grows by 10% every year and becomes 1,33,100 after 3 years. By how many people did it grow during the third year?","options":["11,000","13,310","12,100","10,000"],"answer":2,"explanation":"Working back, the population was 1,33,100/1.1 = 1,21,000 at the end of year 2, so the third-year growth is 1,33,100 − 1,21,000 = 12,100.","difficulty":"hard","questionHi":"एक नगर की जनसंख्या प्रतिवर्ष 10% बढ़ती है और 3 वर्ष बाद 1,33,100 हो जाती है। तीसरे वर्ष में जनसंख्या कितनी बढ़ी?","optionsHi":["11,000","13,310","12,100","10,000"],"explanationHi":"पीछे चलने पर दूसरे वर्ष के अंत में जनसंख्या 1,33,100/1.1 = 1,21,000 थी, अतः तीसरे वर्ष की वृद्धि 1,33,100 − 1,21,000 = 12,100।","subtopic":"population-depreciation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-184","question":"A person spends 80% of his income. His income rises by 20% and his expenditure rises by 25%. What happens to his savings?","options":["They remain unchanged","They increase by 10%","They decrease by 10%","They decrease by 25%"],"answer":0,"explanation":"Take income 100: expenditure 80 and savings 20. Now income is 120 and expenditure 100, so savings are still 20. The rise in expenditure is exactly absorbed by the rise in income.","difficulty":"very-hard","questionHi":"एक व्यक्ति अपनी आय का 80% खर्च करता है। उसकी आय 20% बढ़ती है और खर्च 25% बढ़ता है। उसकी बचत का क्या होता है?","optionsHi":["अपरिवर्तित रहती है","10% बढ़ती है","10% घटती है","25% घटती है"],"explanationHi":"आय 100 लें: खर्च 80 और बचत 20। अब आय 120 और खर्च 100 है, अतः बचत अब भी 20 है। खर्च की वृद्धि आय की वृद्धि में ठीक समा जाती है।","subtopic":"income-expenditure","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-185","question":"A man spends 20% of his income on rent, then 30% of the remainder on food and then 25% of what is left on travel. If ₹4,200 remains, what is his income?","options":["₹8,400","₹12,500","₹14,000","₹10,000"],"answer":3,"explanation":"What remains is 0.8 × 0.7 × 0.75 = 0.42 of the income. So income = 4,200/0.42 = ₹10,000.","difficulty":"hard","questionHi":"एक व्यक्ति अपनी आय का 20% किराये पर, फिर शेष का 30% भोजन पर और फिर बचे हुए का 25% यात्रा पर खर्च करता है। यदि ₹4,200 शेष रहते हैं, तो उसकी आय क्या है?","optionsHi":["₹8,400","₹12,500","₹14,000","₹10,000"],"explanationHi":"शेष राशि आय का 0.8 × 0.7 × 0.75 = 0.42 है। अतः आय = 4,200/0.42 = ₹10,000।","subtopic":"income-expenditure","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-186","question":"Rahul saves 20% of his income. If his income rises by 5% and his expenditure rises by 10%, by what percentage do his savings change?","options":["10% decrease","15% decrease","5% decrease","20% decrease"],"answer":1,"explanation":"Take income 100: expenditure 80, savings 20. New income 105 and expenditure 88, so savings 17. The fall is 3/20 = 15%.","difficulty":"hard","questionHi":"राहुल अपनी आय का 20% बचाता है। यदि उसकी आय 5% और खर्च 10% बढ़ता है, तो उसकी बचत में कितने प्रतिशत परिवर्तन होता है?","optionsHi":["10% की कमी","15% की कमी","5% की कमी","20% की कमी"],"explanationHi":"आय 100 लें: खर्च 80, बचत 20। नई आय 105 और खर्च 88, अतः बचत 17। कमी 3/20 = 15%।","subtopic":"income-expenditure","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-187","question":"The incomes of two persons are in the ratio 5 : 4 and their expenditures are in the ratio 3 : 2. If each saves ₹6,000, what is the income of the first person?","options":["₹12,000","₹15,000","₹18,000","₹20,000"],"answer":1,"explanation":"5k − 3m = 6,000 and 4k − 2m = 6,000. From the second, m = 2k − 3,000; substituting gives 5k − 6k + 9,000 = 6,000, so k = 3,000 and the first income is 5k = ₹15,000.","difficulty":"hard","questionHi":"दो व्यक्तियों की आय का अनुपात 5 : 4 और उनके खर्च का अनुपात 3 : 2 है। यदि प्रत्येक ₹6,000 बचाता है, तो पहले व्यक्ति की आय क्या है?","optionsHi":["₹12,000","₹15,000","₹18,000","₹20,000"],"explanationHi":"5k − 3m = 6,000 और 4k − 2m = 6,000। दूसरे से m = 2k − 3,000; रखने पर 5k − 6k + 9,000 = 6,000, अतः k = 3,000 और पहले की आय 5k = ₹15,000।","subtopic":"income-expenditure","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-188","question":"A family spends 40% of its income on food. If food prices rise by 25% and the income rises by 10%, and the family buys the same quantity of food, what percentage of the new income is spent on food?","options":["50%","44%","41.25%","45.45%"],"answer":3,"explanation":"Take income 100: food costs 40 and becomes 50. New income is 110, so the share is 50/110 = 45.45%.","difficulty":"very-hard","questionHi":"एक परिवार अपनी आय का 40% भोजन पर खर्च करता है। यदि भोजन के दाम 25% और आय 10% बढ़ जाती है, और परिवार भोजन की उतनी ही मात्रा खरीदता है, तो नई आय का कितना प्रतिशत भोजन पर खर्च होगा?","optionsHi":["50%","44%","41.25%","45.45%"],"explanationHi":"आय 100 लें: भोजन का खर्च 40 से बढ़कर 50 हो जाता है। नई आय 110 है, अतः हिस्सा 50/110 = 45.45%।","subtopic":"income-expenditure","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-189","question":"The price of sugar rises by 25% and a family reduces its consumption by 10%. What is the change in its expenditure on sugar?","options":["12.5% increase","15% increase","10% increase","No change"],"answer":0,"explanation":"Expenditure = price × quantity, so the factor is 1.25 × 0.90 = 1.125, an increase of 12.5%.","difficulty":"moderate","questionHi":"चीनी का मूल्य 25% बढ़ जाता है और एक परिवार अपनी खपत 10% घटा देता है। चीनी पर उसके खर्च में क्या परिवर्तन होता है?","optionsHi":["12.5% की वृद्धि","15% की वृद्धि","10% की वृद्धि","कोई परिवर्तन नहीं"],"explanationHi":"खर्च = मूल्य × मात्रा, अतः गुणक 1.25 × 0.90 = 1.125, यानी 12.5% की वृद्धि।","subtopic":"price-consumption","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-190","question":"When the price of rice falls by 20%, a buyer can purchase 4 kg more for ₹1,600. What was the original price per kg?","options":["₹80","₹125","₹100","₹120"],"answer":2,"explanation":"With original price P, ₹1,600 buys 1,600/P kg, and at the new price 0.8P it buys 2,000/P kg. The extra 400/P = 4 gives P = ₹100 (16 kg becomes 20 kg).","difficulty":"hard","questionHi":"जब चावल का मूल्य 20% घट जाता है, तो एक खरीदार ₹1,600 में 4 kg अधिक चावल खरीद सकता है। प्रति kg मूल मूल्य क्या था?","optionsHi":["₹80","₹125","₹100","₹120"],"explanationHi":"मूल मूल्य P होने पर ₹1,600 में 1,600/P kg मिलता है, और नए मूल्य 0.8P पर 2,000/P kg मिलता है। अतिरिक्त 400/P = 4 से P = ₹100 (16 kg की जगह 20 kg)।","subtopic":"price-consumption","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-191","question":"The price of fuel rises by 20% and a motorist cuts his consumption by 10%. Later the price falls by 25% and he raises his consumption by 20%. What is the net change in his fuel expenditure compared with the start?","options":["8% increase","2.8% increase","10% decrease","2.8% decrease"],"answer":3,"explanation":"The factors are 1.2 × 0.9 = 1.08 and then 0.75 × 1.2 = 0.9, giving 1.08 × 0.9 = 0.972. The net change is a 2.8% decrease.","difficulty":"very-hard","questionHi":"ईंधन का मूल्य 20% बढ़ता है और एक मोटर चालक अपनी खपत 10% घटा देता है। बाद में मूल्य 25% घटता है और वह अपनी खपत 20% बढ़ा देता है। आरंभ की तुलना में उसके ईंधन खर्च में कुल क्या परिवर्तन हुआ?","optionsHi":["8% की वृद्धि","2.8% की वृद्धि","10% की कमी","2.8% की कमी"],"explanationHi":"गुणक 1.2 × 0.9 = 1.08 और फिर 0.75 × 1.2 = 0.9 हैं, जिससे 1.08 × 0.9 = 0.972। कुल परिवर्तन 2.8% की कमी है।","subtopic":"price-consumption","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-192","question":"A man spends equal amounts on commodities X and Y. The price of X rises by 25% and the price of Y falls by 20%. If he buys the same quantities as before, how does his total expenditure change?","options":["5% increase","2.5% increase","No change","2.5% decrease"],"answer":1,"explanation":"Let him spend 50 on each. X now costs 62.5 and Y costs 40, so the total is 102.5 against 100. Expenditure rises by 2.5%.","difficulty":"very-hard","questionHi":"एक व्यक्ति वस्तुओं X और Y पर बराबर राशि खर्च करता है। X का मूल्य 25% बढ़ता है और Y का मूल्य 20% घटता है। यदि वह पहले जितनी ही मात्राएँ खरीदता है, तो उसके कुल खर्च में क्या परिवर्तन होता है?","optionsHi":["5% की वृद्धि","2.5% की वृद्धि","कोई परिवर्तन नहीं","2.5% की कमी"],"explanationHi":"मान लें वह प्रत्येक पर 50 खर्च करता है। अब X पर 62.5 और Y पर 40 लगते हैं, अतः कुल 102.5 है जबकि पहले 100 था। खर्च 2.5% बढ़ता है।","subtopic":"price-consumption","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-193","question":"The price of tea rises by 20%. By what percentage must a family reduce its consumption so that its expenditure on tea rises by only 8%?","options":["8%","12%","10%","20%"],"answer":2,"explanation":"1.2 × (1 − x/100) = 1.08 gives 1 − x/100 = 0.9, so the consumption must fall by 10%. Subtracting 20 − 8 = 12 is the usual slip.","difficulty":"hard","questionHi":"चाय का मूल्य 20% बढ़ जाता है। एक परिवार को अपनी खपत कितने प्रतिशत घटानी चाहिए ताकि चाय पर उसका खर्च केवल 8% बढ़े?","optionsHi":["8%","12%","10%","20%"],"explanationHi":"1.2 × (1 − x/100) = 1.08 से 1 − x/100 = 0.9, अतः खपत 10% घटानी होगी। 20 − 8 = 12 निकालना सामान्य भूल है।","subtopic":"price-consumption","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-194","question":"In a two-candidate election 10% of the electors did not vote and 5% of the votes cast were invalid. The winner got 55% of the valid votes and won by 1,710 votes. How many electors are there?","options":["20,000","19,000","18,000","22,000"],"answer":0,"explanation":"Valid votes = 0.9 × 0.95 = 0.855 of the electors. The margin is 55% − 45% = 10% of the valid votes = 0.0855 of the electors = 1,710, so electors = 20,000.","difficulty":"very-hard","questionHi":"दो उम्मीदवारों के चुनाव में 10% मतदाताओं ने मतदान नहीं किया और डाले गए मतों में से 5% अवैध थे। विजेता को वैध मतों का 55% मिला और वह 1,710 मतों से जीता। कुल कितने मतदाता हैं?","optionsHi":["20,000","19,000","18,000","22,000"],"explanationHi":"वैध मत = मतदाताओं का 0.9 × 0.95 = 0.855। अंतर = वैध मतों का 55% − 45% = 10% = मतदाताओं का 0.0855 = 1,710, अतः मतदाता = 20,000।","subtopic":"election-votes","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-195","question":"In an election with three candidates, 10% of the votes polled were invalid. Of the valid votes, A got 40%, B got 35% and C got the rest. A beat C by 1,350 votes. How many votes were polled in all?","options":["10,000","9,000","12,000","11,000"],"answer":0,"explanation":"C got 25% of the valid votes, so A − C = 15% of the valid votes = 1,350, giving 9,000 valid votes. Since these are 90% of the votes polled, the total is 10,000.","difficulty":"hard","questionHi":"तीन उम्मीदवारों वाले चुनाव में डाले गए मतों में से 10% अवैध थे। वैध मतों में से A को 40%, B को 35% और C को शेष मिले। A ने C को 1,350 मतों से हराया। कुल कितने मत डाले गए?","optionsHi":["10,000","9,000","12,000","11,000"],"explanationHi":"C को वैध मतों का 25% मिला, अतः A − C = वैध मतों का 15% = 1,350, जिससे वैध मत 9,000 हैं। ये डाले गए मतों का 90% हैं, अतः कुल मत 10,000।","subtopic":"election-votes","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-196","question":"In a two-candidate contest A got 48% and B got 44% of the total votes polled, and the remaining votes were invalid. A won by 1,000 votes. How many votes were polled?","options":["20,833","12,500","25,000","50,000"],"answer":2,"explanation":"The margin is 48% − 44% = 4% of the votes polled = 1,000, so the votes polled = 25,000. Using 48% as the margin gives 20,833.","difficulty":"hard","questionHi":"दो उम्मीदवारों की प्रतिस्पर्धा में A को डाले गए कुल मतों का 48% और B को 44% मिले, तथा शेष मत अवैध थे। A 1,000 मतों से जीता। कुल कितने मत डाले गए?","optionsHi":["20,833","12,500","25,000","50,000"],"explanationHi":"अंतर = डाले गए मतों का 48% − 44% = 4% = 1,000, अतः डाले गए मत = 25,000। 48% को अंतर मान लेने पर 20,833 आता है।","subtopic":"election-votes","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-197","question":"In an election 80% of the electors voted and 5% of the votes cast were invalid. The winner got 60% of the valid votes and won by 5,472 votes. How many electors are there?","options":["34,200","36,000","28,800","45,600"],"answer":1,"explanation":"Valid votes = 0.8 × 0.95 = 0.76 of the electors. The margin is 60% − 40% = 20% of the valid votes = 0.152 of the electors = 5,472, so electors = 36,000.","difficulty":"very-hard","questionHi":"एक चुनाव में 80% मतदाताओं ने मतदान किया और डाले गए मतों में से 5% अवैध थे। विजेता को वैध मतों का 60% मिला और वह 5,472 मतों से जीता। कुल कितने मतदाता हैं?","optionsHi":["34,200","36,000","28,800","45,600"],"explanationHi":"वैध मत = मतदाताओं का 0.8 × 0.95 = 0.76। अंतर = वैध मतों का 60% − 40% = 20% = मतदाताओं का 0.152 = 5,472, अतः मतदाता = 36,000।","subtopic":"election-votes","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-198","question":"The winner of a two-candidate election got 56% of the valid votes. Had 3% of the valid votes shifted from the winner to the loser, the winner's margin would have been 480 votes. How many valid votes were cast?","options":["16,000","4,000","12,000","8,000"],"answer":3,"explanation":"After the shift the shares are 53% and 47%, so the margin is 6% of the valid votes = 480, giving 8,000. The original margin was 12%, and a shift of 3% changes it by 6 points.","difficulty":"very-hard","questionHi":"दो उम्मीदवारों के चुनाव में विजेता को वैध मतों का 56% मिला। यदि वैध मतों का 3% विजेता से हारने वाले की ओर चला जाता, तो विजेता का अंतर 480 मत होता। कुल कितने वैध मत डाले गए?","optionsHi":["16,000","4,000","12,000","8,000"],"explanationHi":"स्थानांतरण के बाद हिस्से 53% और 47% हैं, अतः अंतर वैध मतों का 6% = 480, जिससे 8,000। मूल अंतर 12% था, और 3% के स्थानांतरण से अंतर 6 अंक बदलता है।","subtopic":"election-votes","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-199","question":"The pass mark in an exam is 35%. Ram scored 20% and failed by 90 marks. Shyam scored 55%. By how many marks did Shyam exceed the pass mark?","options":["90","150","120","180"],"answer":2,"explanation":"The gap 35% − 20% = 15% of the maximum = 90, so the maximum is 600. Shyam has 55% = 330 against a pass mark of 210, i.e. 120 above (20% of 600).","difficulty":"hard","questionHi":"एक परीक्षा में उत्तीर्ण अंक 35% हैं। राम ने 20% अंक पाए और 90 अंकों से अनुत्तीर्ण रहा। श्याम ने 55% अंक पाए। श्याम उत्तीर्ण अंक से कितने अंक अधिक पा गया?","optionsHi":["90","150","120","180"],"explanationHi":"अंतर 35% − 20% = 15% अधिकतम अंक = 90, अतः अधिकतम अंक 600 हैं। श्याम के 55% = 330 अंक हैं जबकि उत्तीर्ण अंक 210 हैं, अर्थात् 120 अधिक (600 का 20%)।","subtopic":"marks-exams","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-200","question":"In an exam 65% of the candidates passed in Mathematics, 72% passed in English and 12% failed in both subjects. What percentage passed in both?","options":["49%","37%","53%","47%"],"answer":0,"explanation":"Passed in at least one = 100 − 12 = 88%. Passed both = 65 + 72 − 88 = 49%.","difficulty":"moderate","questionHi":"एक परीक्षा में 65% परीक्षार्थी गणित में, 72% अंग्रेज़ी में उत्तीर्ण हुए और 12% दोनों विषयों में अनुत्तीर्ण रहे। दोनों में उत्तीर्ण होने वालों का प्रतिशत क्या है?","optionsHi":["49%","37%","53%","47%"],"explanationHi":"कम से कम एक में उत्तीर्ण = 100 − 12 = 88%। दोनों में उत्तीर्ण = 65 + 72 − 88 = 49%।","subtopic":"marks-exams","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-201","question":"A test has 150 questions with +4 for each correct answer and −1 for each wrong answer. A candidate attempted 80% of the questions and scored 285. What percentage of the questions he attempted were correct?","options":["54%","60%","70%","67.5%"],"answer":3,"explanation":"He attempted 120 questions. If x are correct, 4x − (120 − x) = 285 gives x = 81. So 81/120 = 67.5% of his attempts; 54% is 81 out of all 150 questions.","difficulty":"very-hard","questionHi":"एक परीक्षण में 150 प्रश्न हैं, प्रत्येक सही उत्तर के +4 और प्रत्येक गलत उत्तर के −1 अंक हैं। एक परीक्षार्थी ने 80% प्रश्न हल किए और 285 अंक पाए। उसके द्वारा हल किए गए प्रश्नों में कितने प्रतिशत सही थे?","optionsHi":["54%","60%","70%","67.5%"],"explanationHi":"उसने 120 प्रश्न हल किए। यदि x सही हैं, तो 4x − (120 − x) = 285 से x = 81। अतः हल किए गए प्रश्नों का 81/120 = 67.5%; 54% कुल 150 प्रश्नों में से 81 का प्रतिशत है।","subtopic":"marks-exams","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-202","question":"In a class 40% of the students are girls. 70% of the boys passed and 60% of all the students passed. What percentage of the girls passed?","options":["50%","45%","42%","60%"],"answer":1,"explanation":"Per 100 students, 60 are boys and 70% of them, 42, passed. Total passed = 60, so 18 girls passed out of 40, which is 45%.","difficulty":"hard","questionHi":"एक कक्षा में 40% विद्यार्थी लड़कियाँ हैं। 70% लड़के उत्तीर्ण हुए और सभी विद्यार्थियों में 60% उत्तीर्ण हुए। कितने प्रतिशत लड़कियाँ उत्तीर्ण हुईं?","optionsHi":["50%","45%","42%","60%"],"explanationHi":"प्रति 100 विद्यार्थियों में 60 लड़के हैं और उनमें से 70%, यानी 42 उत्तीर्ण हुए। कुल उत्तीर्ण = 60, अतः 40 लड़कियों में से 18 उत्तीर्ण हुईं, जो 45% है।","subtopic":"marks-exams","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-203","question":"Papers A, B and C carry 150, 100 and 50 marks. A student scores 60% in A, 70% in B and 80% in C. What is his overall percentage?","options":["70%","66.67%","65%","62.5%"],"answer":1,"explanation":"Marks = 90 + 70 + 40 = 200 out of 300, i.e. 66.67%. The simple average 70% ignores the different maximum marks.","difficulty":"hard","questionHi":"प्रश्नपत्र A, B और C के पूर्णांक क्रमशः 150, 100 और 50 हैं। एक विद्यार्थी A में 60%, B में 70% और C में 80% अंक पाता है। उसका कुल प्रतिशत क्या है?","optionsHi":["70%","66.67%","65%","62.5%"],"explanationHi":"प्राप्त अंक = 90 + 70 + 40 = 200, कुल 300 में से, अर्थात् 66.67%। साधारण औसत 70% में भिन्न पूर्णांकों की उपेक्षा है।","subtopic":"marks-exams","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-204","question":"A 20-litre mixture of milk and water contains 10% water. How many litres of water must be added to make the water 25% of the new mixture?","options":["2 litres","5 litres","6 litres","4 litres"],"answer":3,"explanation":"Milk stays 18 L and must become 75% of the new mixture, so the new total is 24 L. Water added = 24 − 20 = 4 L.","difficulty":"moderate","questionHi":"दूध और पानी के 20 लीटर मिश्रण में 10% पानी है। नए मिश्रण में पानी 25% करने के लिए कितने लीटर पानी मिलाना होगा?","optionsHi":["2 लीटर","5 लीटर","6 लीटर","4 लीटर"],"explanationHi":"दूध 18 L ही रहता है और नए मिश्रण का 75% होना चाहिए, अतः नया कुल 24 L है। मिलाया गया पानी = 24 − 20 = 4 L।","subtopic":"mixtures-concentration","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-205","question":"A 40-litre salt solution contains 15% salt. How many litres of water must evaporate to make it a 20% salt solution?","options":["10 litres","8 litres","12 litres","5 litres"],"answer":0,"explanation":"Salt = 6 L stays fixed and must be 20% of the new solution, so the new volume is 30 L. Water evaporated = 40 − 30 = 10 L.","difficulty":"hard","questionHi":"40 लीटर के एक नमक के घोल में 15% नमक है। इसे 20% नमक का घोल बनाने के लिए कितने लीटर पानी वाष्पित होना चाहिए?","optionsHi":["10 लीटर","8 लीटर","12 लीटर","5 लीटर"],"explanationHi":"नमक = 6 L स्थिर रहता है और नए घोल का 20% होना चाहिए, अतः नया आयतन 30 L है। वाष्पित पानी = 40 − 30 = 10 L।","subtopic":"mixtures-concentration","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-206","question":"Vessel A holds water and milk in the ratio 1 : 4 and vessel B holds them in the ratio 3 : 2. If the contents of A and B are mixed in the ratio 3 : 2, what percentage of the mixture is milk?","options":["60%","66%","64%","56%"],"answer":2,"explanation":"A is 80% milk and B is 40% milk. In the 3 : 2 mixture, milk = (3 × 80 + 2 × 40)/5 = 320/5 = 64%.","difficulty":"hard","questionHi":"बर्तन A में पानी और दूध 1 : 4 के अनुपात में हैं और बर्तन B में 3 : 2 के अनुपात में। यदि A और B की सामग्री 3 : 2 के अनुपात में मिलाई जाए, तो मिश्रण में दूध का प्रतिशत क्या है?","optionsHi":["60%","66%","64%","56%"],"explanationHi":"A में 80% दूध और B में 40% दूध है। 3 : 2 वाले मिश्रण में दूध = (3 × 80 + 2 × 40)/5 = 320/5 = 64%।","subtopic":"mixtures-concentration","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-207","question":"Fresh fruit contains 90% water and dried fruit contains 20% water. How many kg of dried fruit can be obtained from 50 kg of fresh fruit?","options":["10 kg","12.5 kg","6 kg","6.25 kg"],"answer":3,"explanation":"The solid content stays the same: 10% of 50 = 5 kg. In dried fruit this is 80%, so the weight is 5/0.8 = 6.25 kg.","difficulty":"very-hard","questionHi":"ताज़े फल में 90% पानी और सूखे फल में 20% पानी होता है। 50 kg ताज़े फल से कितने kg सूखा फल प्राप्त हो सकता है?","optionsHi":["10 kg","12.5 kg","6 kg","6.25 kg"],"explanationHi":"ठोस पदार्थ की मात्रा समान रहती है: 50 का 10% = 5 kg। सूखे फल में यह 80% है, अतः भार 5/0.8 = 6.25 kg।","subtopic":"mixtures-concentration","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-percentage-208","question":"A vessel contains 40 litres of pure acid. 8 litres are drawn off and replaced with water, and the same operation is repeated once more. How much acid is left?","options":["24 litres","25.6 litres","28.8 litres","27.2 litres"],"answer":1,"explanation":"Each step keeps 32/40 = 4/5 of the acid, so the acid left is 40 × (4/5)² = 25.6 L. The second 8 L drawn off is a mixture, not pure acid, so 24 L is wrong.","difficulty":"very-hard","questionHi":"एक बर्तन में 40 लीटर शुद्ध अम्ल है। 8 लीटर निकालकर उसकी जगह पानी डाला जाता है और यही क्रिया एक बार और दोहराई जाती है। कितना अम्ल शेष रहता है?","optionsHi":["24 लीटर","25.6 लीटर","28.8 लीटर","27.2 लीटर"],"explanationHi":"प्रत्येक चरण में अम्ल का 32/40 = 4/5 भाग बचता है, अतः शेष अम्ल 40 × (4/5)² = 25.6 L। दूसरी बार निकाला गया 8 L मिश्रण है, शुद्ध अम्ल नहीं, इसलिए 24 L गलत है।","subtopic":"mixtures-concentration","source":"SSC CGL Tier 2 · IBPS PO Mains"},
];

export default questions;
